import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum View {
  HOME = 'HOME',
  CARSPOTTING = 'CARSPOTTING',
  EVENTI = 'EVENTI',
}

export interface User {
  isLoggedIn: boolean;
  username?: string;
}

import React, { useState } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState({ isLoggedIn: false });

  const handleLogin = (username: string) => {
    setUser({ isLoggedIn: true, username });
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    setUser({ isLoggedIn: false });
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => setCurrentView(View.HOME)}
      />

      <main className="pt-20 px-4 md:px-8 max-w-7xl mx-auto">
        {currentView === View.HOME && (
          <Hero 
            onSelectView={(view) => setCurrentView(view)} 
          />
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-12 text-center animate-in fade-in duration-500">
            <h2 className="text-4xl font-brand text-brick-red mb-4">CARSPOTTING</h2>
            <p className="text-gray-400 max-w-2xl mx-auto">
              Sezione dedicata agli avvistamenti di auto esotiche e storiche nel Nord Italia. 
              Carica le tue foto e condividi la passione.
            </p>
            <button 
              onClick={() => setCurrentView(View.HOME)}
              className="mt-8 px-6 py-2 border border-brick-red text-brick-red hover:bg-brick-red hover:text-white transition-all"
            >
              Torna alla Home
            </button>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-12 text-center animate-in fade-in duration-500">
            <h2 className="text-4xl font-brand text-brick-red mb-4">CALENDARIO EVENTI</h2>
            <p className="text-gray-400 max-w-2xl mx-auto">
              Resta aggiornato su tutti i raduni, track day e fiere automotive nel Nord Italia.
            </p>
            <button 
              onClick={() => setCurrentView(View.HOME)}
              className="mt-8 px-6 py-2 border border-brick-red text-brick-red hover:bg-brick-red hover:text-white transition-all"
            >
              Torna alla Home
            </button>
          </div>
        )}
      </main>

      {isAuthModalOpen && (
        <AuthModal 
          onClose={() => setIsAuthModalOpen(false)} 
          onLogin={handleLogin}
        />
      )}

      <footer className="mt-20 py-8 border-t border-gray-800 text-center text-sm text-gray-500">
        &copy; {new Date().getFullYear()} raduninorditalia. Tutti i diritti riservati.
      </footer>
    </div>
  );
};

export default App;

