import React, { useState } from 'react';

interface AuthModalProps {
  onClose: () => void;
  onLogin: (username: string) => void;
}

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLogin }) => {
  const [username, setUsername] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (username.trim()) {
      onLogin(username);
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/90 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      {/* Modal */}
      <div className="relative bg-panel-gray border border-gray-800 w-full max-w-md p-8 shadow-2xl animate-in zoom-in duration-200">
        <h3 className="text-2xl font-brand text-white mb-6">ACCESSO UTENTE</h3>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Username</label>
            <input 
              autoFocus
              type="text" 
              value={username}
              onChange={(e) => setUsername(e.target.value)}
