import { GoogleGenAI, Type } from "@google/genai";

/**
 * Servizio per l'integrazione di Gemini.
 * Può essere utilizzato per generare descrizioni di eventi o identificare auto da foto caricate.
 */
export const getEventAdvice = async (eventDescription: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analizza questo evento automotive e suggerisci come migliorarne la sponsorizzazione: ${eventDescription}`,
      config: {
        temperature: 0.7,
        topK: 40,
        topP: 0.95,
      },
    });

    return response.text;
  } catch (error) {
    console.error("Errore durante la chiamata a Gemini:", error);
    return "Impossibile ottenere suggerimenti al momento.";
  }
};

