import React, { useState } from 'react';

interface AuthModalProps {
  onClose: () => void;
  onLogin: (username: string) => void;
}

type AuthMode = 'login' | 'register';

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [formData, setFormData] = useState({
    identifier: '', // Email o Username per login
    username: '',   // Per registrazione
    email: '',      // Per registrazione
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (mode === 'login') {
      // Simulazione login
      if (formData.identifier.trim() && formData.password.trim()) {
        onLogin(formData.identifier);
      } else {
        setError('Inserisci credenziali valide');
      }
    } else {
      // Simulazione registrazione
      if (formData.password !== formData.confirmPassword) {
        setError('Le password non coincidono');
        return;
      }
      if (formData.username && formData.email && formData.password) {
        onLogin(formData.username);
      } else {
        setError('Compila tutti i campi');
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/90 backdrop-blur-sm"
        onClick={onClose}
      ></div>

      {/* Modal */}
      <div className="relative bg-panel-gray border border-gray-800 w-full max-w-md p-8 shadow-2xl animate-in zoom-in duration-200">
        <div className="flex justify-between items-center mb-8 border-b border-gray-800 pb-4">
          <button 
            onClick={() => { setMode('login'); setError(''); }}
            className={`text-xl font-brand transition-colors ${mode === 'login' ? 'text-brick-red' : 'text-gray-600 hover:text-gray-400'}`}
          >
            ACCEDI
          </button>
          <button 
            onClick={() => { setMode('register'); setError(''); }}
            className={`text-xl font-brand transition-colors ${mode === 'register' ? 'text-brick-red' : 'text-gray-600 hover:text-gray-400'}`}
          >
            REGISTRATI
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <div className="bg-brick-red/10 border border-brick-red/30 p-3 text-brick-red text-xs font-bold text-center">
              {error.toUpperCase()}
            </div>
          )}

          {mode === 'login' ? (
            <>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Email o Nome Utente</label>
                <input 
                  type="text" 
                  name="identifier"
                  value={formData.identifier}
                  onChange={handleInputChange}
                  placeholder="Inserisci email o username"
                  className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Password</label>
                <input 
                  type="password" 
                  name="password"
                  value={formData.password}
                  onChange={handleInputChange}
                  placeholder="••••••••"
                  className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                  required
                />
              </div>
            </>
          ) : (
            <>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Nome Utente</label>
                <input 
                  type="text" 
                  name="username"
                  value={formData.username}
                  onChange={handleInputChange}
                  placeholder="Nome utente"
                  className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                  required
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Email</label>
                <input 
                  type="email" 
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  placeholder="esempio@mail.com"
                  className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                  required
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Password</label>
                  <input 
                    type="password" 
                    name="password"
                    value={formData.password}
                    onChange={handleInputChange}
                    placeholder="••••••••"
                    className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Conferma</label>
                  <input 
                    type="password" 
                    name="confirmPassword"
                    value={formData.confirmPassword}
                    onChange={handleInputChange}
                    placeholder="••••••••"
                    className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                    required
                  />
                </div>
              </div>
            </>
          )}

          <button 
            type="submit"
            className="w-full bg-brick-red text-white py-3 font-bold hover:bg-brick-red/90 transition-all active:scale-[0.98] mt-4 tracking-widest"
          >
            {mode === 'login' ? 'ACCEDI' : 'REGISTRATI'}
          </button>
        </form>

        <button 
          onClick={onClose}
          className="mt-6 w-full text-center text-gray-600 text-[10px] font-bold uppercase tracking-[0.2em] hover:text-gray-400 transition-colors"
        >
          Annulla Procedura
        </button>
      </div>
    </div>
  );
};

export default AuthModal;

