import React, { useState } from 'react';

interface AuthModalProps {
  onClose: () => void;
  onLogin: (username: string) => void;
}

type AuthMode = 'login' | 'register';

interface SavedUser {
  username: string;
  email: string;
  password: string;
}

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [formData, setFormData] = useState({
    identifier: '', // Email o Username per login
    username: '',   // Per registrazione
    email: '',      // Per registrazione
    password: '',
    confirmPassword: ''
  });
  const [error, setError] = useState('');

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
  };

  const getSavedUsers = (): SavedUser[] => {
    const users = localStorage.getItem('rn_users');
    return users ? JSON.parse(users) : [];
  };

  const saveUser = (newUser: SavedUser) => {
    const users = getSavedUsers();
    users.push(newUser);
    localStorage.setItem('rn_users', JSON.stringify(users));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const users = getSavedUsers();

    if (mode === 'login') {
      // Ricerca utente per nome utente o email
      const foundUser = users.find(u => 
        (u.username === formData.identifier || u.email === formData.identifier) && 
        u.password === formData.password
      );

      if (foundUser) {
        onLogin(foundUser.username);
      } else {
        setError('Credenziali errate o utente non trovato');
      }
    } else {
      // Registrazione
      if (formData.password !== formData.confirmPassword) {
        setError('Le password non coincidono');
        return;
      }

      // Controllo se l'utente esiste già
      const userExists = users.some(u => u.username === formData.username || u.email === formData.email);
      if (userExists) {
        setError('Nome utente o email già in uso');
        return;
      }

      if (formData.username && formData.email && formData.password) {
        const newUser: SavedUser = {
          username: formData.username,
          email: formData.email,
          password: formData.password
        };
        saveUser(newUser);
        onLogin(formData.username);
      } else {
        setError('Compila tutti i campi');
      }
    }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/95 backdrop-blur-md"
        onClick={onClose}
      ></div>

      {/* Pulsante Indietro minimale nell'angolo in alto a sinistra */}
      <button 
        onClick={onClose}
        className="fixed top-8 left-8 flex items-center gap-3 text-gray-500 hover:text-brick-red transition-all group z-[110] outline-none"
        aria-label="Chiudi"
      >
        <div className="transition-transform group-hover:-translate-x-1 duration-300">
          <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="19" y1="12" x2="5" y2="12"></line>
            <polyline points="12 19 5 12 12 5"></polyline>
          </svg>
        </div>
        <span className="text-[11px] font-bold uppercase tracking-[0.4em] opacity-0 translate-x-[-10px] group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-300 ease-out">
          Indietro
        </span>
      </button>

      {/* Modal Rectangle */}
      <div className="relative w-full max-w-md animate-in zoom-in duration-300">
        <div className="bg-panel-gray border border-gray-800 p-8 shadow-2xl">
          <div className="flex justify-between items-center mb-8 border-b border-gray-800 pb-4">
            <button 
              onClick={() => { setMode('login'); setError(''); }}
              className={`text-xl font-brand transition-colors ${mode === 'login' ? 'text-brick-red' : 'text-gray-600 hover:text-gray-400'}`}
            >
              ACCEDI
            </button>
            <button 
              onClick={() => { setMode('register'); setError(''); }}
              className={`text-xl font-brand transition-colors ${mode === 'register' ? 'text-brick-red' : 'text-gray-600 hover:text-gray-400'}`}
            >
              REGISTRATI
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {error && (
              <div className="bg-brick-red/10 border border-brick-red/30 p-3 text-brick-red text-xs font-bold text-center uppercase tracking-tight">
                {error}
              </div>
            )}

            {mode === 'login' ? (
              <>
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Email o Nome Utente</label>
                  <input 
                    type="text" 
                    name="identifier"
                    value={formData.identifier}
                    onChange={handleInputChange}
                    placeholder="Inserisci email o username"
                    className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Password</label>
                  <input 
                    type="password" 
                    name="password"
                    value={formData.password}
                    onChange={handleInputChange}
                    placeholder="••••••••"
                    className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                    required
                  />
                </div>
              </>
            ) : (
              <>
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Nome Utente</label>
                  <input 
                    type="text" 
                    name="username"
                    value={formData.username}
                    onChange={handleInputChange}
                    placeholder="Nome utente"
                    className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                    required
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Email</label>
                  <input 
                    type="email" 
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    placeholder="esempio@mail.com"
                    className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                    required
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Password</label>
                    <input 
                      type="password" 
                      name="password"
                      value={formData.password}
                      onChange={handleInputChange}
                      placeholder="••••••••"
                      className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Conferma</label>
                    <input 
                      type="password" 
                      name="confirmPassword"
                      value={formData.confirmPassword}
                      onChange={handleInputChange}
                      placeholder="••••••••"
                      className="w-full bg-black border border-gray-700 p-3 text-white focus:border-brick-red outline-none transition-colors text-sm"
                      required
                    />
                  </div>
                </div>
              </>
            )}

            <button 
              type="submit"
              className="w-full bg-brick-red text-white py-3 font-bold hover:bg-brick-red/90 transition-all active:scale-[0.98] mt-4 tracking-widest"
            >
              {mode === 'login' ? 'ACCEDI' : 'REGISTRATI'}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AuthModal;

/**
 * Database Locale per RaduniNordItalia
 * Gestisce la persistenza dei dati nel localStorage in modo strutturato.
 */

const STORAGE_KEYS = {
  USERS: 'rni_db_users',
  EVENTS: 'rni_db_events',
  SPOTS: 'rni_db_spots',
  SESSION: 'rni_session'
};

export const db = {
  // Gestione Utenti e Autenticazione
  users: {
    getAll: () => JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]'),

    create: (userData: any) => {
      const users = db.users.getAll();
      const newUser = { ...userData, id: Date.now(), createdAt: new Date().toISOString() };
      users.push(newUser);
      localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(users));
      return newUser;
    },

    findByUsername: (username: string) => {
      return db.users.getAll().find((u: any) => u.username === username || u.email === username);
    }
  },

  // Gestione Sessione Attiva
  auth: {
    login: (username: string) => {
      const session = { username, token: `mock_token_${Date.now()}`, timestamp: Date.now() };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },

    logout: () => {
      localStorage.removeItem(STORAGE_KEYS.SESSION);
    },

    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      return session ? JSON.parse(session) : null;
    }
  },

  // Placeholder per Eventi e Spots (espandibili in futuro)
  events: {
    getAll: () => JSON.parse(localStorage.getItem(STORAGE_KEYS.EVENTS) || '[]'),
    add: (event: any) => {
      const events = db.events.getAll();
      events.push({ ...event, id: Date.now() });
      localStorage.setItem(STORAGE_KEYS.EVENTS, JSON.stringify(events));
    }
  },

  spots: {
    getAll: () => JSON.parse(localStorage.getItem(STORAGE_KEYS.SPOTS) || '[]'),
    add: (spot: any) => {
      const spots = db.spots.getAll();
      spots.push({ ...spot, id: Date.now() });
      localStorage.setItem(STORAGE_KEYS.SPOTS, JSON.stringify(spots));
    }
  }
};

