const STORAGE_KEYS = {
  USERS: 'rni_db_users',
  EVENTS: 'rni_db_events',
  SPOTS: 'rni_db_spots',
  SESSION: 'rni_session'
};

export const db = {
  // Gestione Utenti
  users: {
    getAll: async () => {
      if (supabase) {
        const { data, error } = await supabase.from('users').select('*');
        if (error) console.error(error);
        return data || [];
      }
      return JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
    },

    create: async (userData: any) => {
      if (supabase) {
        const { data, error } = await supabase.from('users').insert([
          { ...userData, created_at: new Date() }
        ]).select();
        if (error) throw error;
        return data[0];
      } else {
        const users = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
        const newUser = { ...userData, id: Date.now(), createdAt: new Date().toISOString() };
        users.push(newUser);
        localStorage.setItem(STORAGE_KEYS.USERS, JSON.stringify(users));
        return newUser;
      }
    },

    findByUsername: async (username: string) => {
      if (supabase) {
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .or(`username.eq.${username},email.eq.${username}`)
          .single();
        if (error && error.code !== 'PGRST116') console.error(error);
        return data;
      }
      const users = JSON.parse(localStorage.getItem(STORAGE_KEYS.USERS) || '[]');
      return users.find((u: any) => u.username === username || u.email === username);
    }
  },

  // Sessione
  auth: {
    login: (username: string) => {
      const session = { username, timestamp: Date.now() };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      return session ? JSON.parse(session) : null;
    }
  }
};

