import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View } from './types';
import { db } from './services/db';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<{ isLoggedIn: boolean; username?: string }>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session) {
      setUser({ isLoggedIn: true, username: session.username });
    }
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData);
      setSpots(spotsData);
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (username: string) => {
    db.auth.login(username);
    setUser({ isLoggedIn: true, username });
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
  };

  const handleAddEvent = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newEvent = {
      title: formData.get('title') as string,
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      description: formData.get('description') as string,
    };
    await db.events.create(newEvent);
    loadData();
    (e.target as HTMLFormElement).reset();
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newSpot = {
      car_model: formData.get('car_model') as string,
      location: formData.get('location') as string,
      spotted_by: user.username || 'Anonimo',
    };
    await db.spots.create(newSpot);
    loadData();
    (e.target as HTMLFormElement).reset();
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white pb-20">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => setCurrentView(View.HOME)}
      />

      <main className="pt-24 px-4 md:px-8 max-w-7xl mx-auto">
        {currentView === View.HOME && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center mb-10">
              <p className="text-gray-500 uppercase tracking-[0.3em] text-xs font-bold mb-2">
                Automotive Community
              </p>
              <h2 className="text-xl md:text-2xl text-light-gray font-light max-w-xl mx-auto leading-relaxed">
                Il punto di riferimento per la passione <span className="text-brick-red font-semibold">automotive</span> nel Nord Italia.
              </h2>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-6 animate-in fade-in duration-500 max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red">CARSPOTTING</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            {user.isLoggedIn && (
              <form onSubmit={handleAddSpot} className="bg-panel-gray border border-gray-800 p-6 mb-10 grid grid-cols-1 md:grid-cols-3 gap-4">
                <input name="car_model" placeholder="Modello Auto" className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red" required />
                <input name="location" placeholder="Luogo Avvistamento" className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red" required />
                <button type="submit" className="bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3">Invia Segnalazione</button>
              </form>
            )}

            <div className="space-y-4">
              {spots.length === 0 ? (
                <p className="text-center py-10 text-gray-600 italic">Nessun avvistamento recente.</p>
              ) : (
                spots.map(spot => (
                  <div key={spot.id} className="bg-panel-gray border-l-2 border-brick-red p-4 flex justify-between items-center group hover:bg-white/5 transition-colors">
                    <div>
                      <h3 className="text-lg font-bold text-white uppercase tracking-tight">{spot.car_model}</h3>
                      <p className="text-xs text-gray-500 uppercase tracking-widest">{spot.location}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] text-gray-600 uppercase">Segnalato da</p>
                      <p className="text-xs font-bold text-brick-red uppercase">{spot.spotted_by}</p>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-6 animate-in fade-in duration-500 max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red">EVENTI</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            {user.isLoggedIn && (
              <form onSubmit={handleAddEvent} className="bg-panel-gray border border-gray-800 p-6 mb-10 space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input name="title" placeholder="Nome dell'Evento" className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red" required />
                  <input name="date" type="date" className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red" required />
                </div>
                <input name="location" placeholder="Località (es. Monza, MI)" className="bg-black border border-gray-800 p-3 text-sm w-full outline-none focus:border-brick-red" required />
                <textarea name="description" placeholder="Breve descrizione..." className="bg-black border border-gray-800 p-3 text-sm w-full h-20 outline-none focus:border-brick-red" />
                <button type="submit" className="w-full bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3">Aggiungi al Calendario</button>
              </form>
            )}

            <div className="grid grid-cols-1 gap-4">
              {events.length === 0 ? (
                <p className="text-center py-10 text-gray-600 italic">Nessun evento in programma.</p>
              ) : (
                events.map(event => (
                  <div key={event.id} className="bg-panel-gray border border-gray-800 p-6 hover:border-gray-600 transition-all">
                    <div className="flex justify-between items-start mb-2">
                      <h3 className="text-xl font-bold text-white uppercase tracking-tighter">{event.title}</h3>
                      <span className="text-brick-red font-brand text-sm">{new Date(event.date).toLocaleDateString('it-IT')}</span>
                    </div>
                    <p className="text-xs text-gray-400 uppercase tracking-widest mb-4">{event.location}</p>
                    <p className="text-sm text-gray-500 leading-relaxed">{event.description}</p>
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </main>

      {isAuthModalOpen && (
        <AuthModal 
          onClose={() => setIsAuthModalOpen(false)} 
          onLogin={handleLogin}
        />
      )}

      <footer className="fixed bottom-0 left-0 right-0 py-4 bg-black border-t border-gray-900 text-center text-[9px] text-gray-700 z-40">
        <p className="font-brand tracking-[0.5em] text-brick-red/50 uppercase">RADUNINORDITALIA &copy; {new Date().getFullYear()}</p>
      </footer>
    </div>
  );
