const STORAGE_KEYS = {
  USERS: 'rni_db_users',
  EVENTS: 'rni_db_events',
  SPOTS: 'rni_db_spots',
  SESSION: 'rni_session'
};

export const db = {
  users: {
    create: async (userData: any) => {
      if (supabase) {
        const { data, error } = await supabase.from('users').insert([
          { username: userData.username, email: userData.email, password: userData.password }
        ]).select();
        if (error) throw error;
        return data[0];
      }
      return null;
    },
    findByUsername: async (username: string) => {
      if (supabase) {
        // Usiamo un filtro più robusto per username o email
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .or(`username.eq."${username}",email.eq."${username}"`)
          .maybeSingle();
        if (error) {
          console.error("Errore findByUsername:", error.message);
          return null;
        }
        return data;
      }
      return null;
    }
  },

  events: {
    getAll: async () => {
      if (supabase) {
        const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
        if (error) {
          console.error("Errore getAll Events:", error.message);
          throw error;
        }
        return data || [];
      }
      return [];
    },
    create: async (eventData: any) => {
      if (supabase) {
        const { data, error } = await supabase.from('events').insert([eventData]).select();
        if (error) throw error;
        return data[0];
      }
    }
  },

  spots: {
    getAll: async () => {
      if (supabase) {
        const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
        if (error) {
          console.error("Errore getAll Spots:", error.message);
          throw error;
        }
        return data || [];
      }
      return [];
    },
    create: async (spotData: any) => {
      if (supabase) {
        const { data, error } = await supabase.from('spots').insert([spotData]).select();
        if (error) throw error;
        return data[0];
      }
    }
  },

  auth: {
    login: (username: string) => {
      const session = { username, timestamp: Date.now() };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      return session ? JSON.parse(session) : null;
    }
  }
};

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Analizza un'immagine e identifica l'auto presente.
 */
export const identifyCarFromImage = async (base64Image: string, mimeType: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Image,
              mimeType: mimeType
            }
          },
          {
            text: "Identifica la marca e il modello esatto dell'auto in questa foto. Rispondi SOLO con il nome dell'auto (es: 'Ferrari 488 Pista'). Se non sei sicuro o non ci sono auto, rispondi 'Sconosciuta'."
          }
        ]
      },
      config: {
        temperature: 0.4,
      },
    });

    return response.text?.trim() || "Sconosciuta";
  } catch (error) {
    console.error("Errore analisi AI:", error);
    throw new Error("Errore durante l'analisi dell'immagine.");
  }
};

export const getEventAdvice = async (eventDescription: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Analizza questo evento automotive e suggerisci come migliorarne la sponsorizzazione: ${eventDescription}`,
    });
    return response.text;
  } catch (error) {
    console.error("Errore:", error);
    return "Suggerimento non disponibile.";
  }
};

