    const file = e.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    setErrorMessage(null);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = async () => {
        const base64Data = (reader.result as string).split(',')[1];
        const carModel = await identifyCarFromImage(base64Data, file.type);
        setScannedCarModel(carModel !== 'Sconosciuta' ? carModel : '');
        if (carModel === 'Sconosciuta') {
          alert("L'AI non è riuscita a identificare l'auto. Inseriscila manualmente.");
        }
        setIsAnalyzing(false);
