const supabase = (SUPABASE_URL && SUPABASE_ANON_KEY) 
  ? createClient(SUPABASE_URL, SUPABASE_ANON_KEY) 
  : null;

export const isCloudMode = !!supabase;

const STORAGE_KEYS = {
  USERS: 'rni_db_users',
  EVENTS: 'rni_db_events',
  SPOTS: 'rni_db_spots',
  SESSION: 'rni_session'
};

export const db = {
  users: {
    create: async (userData: any) => {
      if (supabase) {
        const { data, error } = await supabase.from('users').insert([
          { username: userData.username, email: userData.email, password: userData.password }
        ]).select();
        if (error) throw error;
        return data[0];
      }
      return null;
    },
    findByUsername: async (username: string) => {
      if (supabase) {
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .or(`username.eq."${username}",email.eq."${username}"`)
          .maybeSingle();
        if (error) {
          console.error("Errore findByUsername:", error.message);
          return null;
        }
        return data;
      }
      return null;
    }
  },

  events: {
    getAll: async () => {
      if (supabase) {
        const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
        if (error) {
          console.error("Errore getAll Events:", error.message);
          throw error;
        }
        return data || [];
      }
      return [];
    },
    create: async (eventData: any) => {
      if (supabase) {
        const { data, error } = await supabase.from('events').insert([eventData]).select();
        if (error) throw error;
        return data[0];
      }
    }
  },

  spots: {
    getAll: async () => {
      if (supabase) {
        const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
        if (error) {
          console.error("Errore getAll Spots:", error.message);
          throw error;
        }
        return data || [];
      }
      return [];
    },
    create: async (spotData: any) => {
      if (supabase) {
        // spotData ora include image_data (base64)
        const { data, error } = await supabase.from('spots').insert([spotData]).select();
        if (error) throw error;
        return data[0];
      }
    }
  },

  auth: {
    login: (username: string) => {
      const session = { username, timestamp: Date.now() };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      return session ? JSON.parse(session) : null;
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View } from './types';
import { db } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<{ isLoggedIn: boolean; username?: string }>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [scannedCarModel, setScannedCarModel] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session) {
      setUser({ isLoggedIn: true, username: session.username });
    }
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    setErrorMessage(null);
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
    } catch (err: any) {
      setErrorMessage("Errore nel caricamento dei dati. Verifica la connessione.");
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (username: string) => {
    db.auth.login(username);
    setUser({ isLoggedIn: true, username });
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    setErrorMessage(null);

    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const result = reader.result as string;

        // Impostiamo l'anteprima usando il Base64 (result)
        setPreviewUrl(result);
        setImageBase64(result);

        const mimeTypeMatch = result.match(/^data:(image\/[a-z]+);base64,/);
        const mimeType = mimeTypeMatch ? mimeTypeMatch[1] : (file.type || 'image/jpeg');
        const base64Data = result.split(',')[1];

        if (!base64Data) throw new Error("Dati immagine non validi.");

        const carModel = await identifyCarFromImage(base64Data, mimeType);

        if (carModel === 'Sconosciuta') {
          alert("L'AI non è riuscita a identificare l'auto. Inseriscila manualmente.");
          setScannedCarModel('');
        } else {
          setScannedCarModel(carModel);
        }
      } catch (err: any) {
        console.error("Errore analisi AI:", err);
        setErrorMessage("Errore durante l'analisi dell'immagine: " + (err.message || "riprova con un'altra foto."));
      } finally {
        setIsAnalyzing(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.onerror = () => {
      setErrorMessage("Errore nel caricamento del file locale.");
      setIsAnalyzing(false);
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!imageBase64) {
      alert("Devi allegare una foto per inviare uno spot!");
      return;
    }

    const formData = new FormData(e.currentTarget);
    const newSpot = {
      car_model: (formData.get('car_model') as string) || scannedCarModel,
      location: "Posizione Rilevata",
      spotted_by: user.username || 'Anonimo',
      image_data: imageBase64
    };

    try {
      await db.spots.create(newSpot);
      setScannedCarModel('');
      setPreviewUrl(null);
      setImageBase64(null);
      loadData();
      (e.target as HTMLFormElement).reset();
    } catch (err: any) {
      alert("Errore salvataggio: " + err.message);
    }
  };

  const handleAddEvent = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newEvent = {
      title: formData.get('title') as string,
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      description: formData.get('description') as string,
    };
    try {
      await db.events.create(newEvent);
      loadData();
      (e.target as HTMLFormElement).reset();
    } catch (err: any) {
      alert("Errore salvataggio evento: " + err.message);
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white pb-20">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => setCurrentView(View.HOME)}
      />

      <main className="pt-24 px-4 md:px-8 max-w-7xl mx-auto">
        {errorMessage && (
          <div className="mb-6 bg-brick-red/20 border border-brick-red/50 p-4 text-brick-red text-xs font-bold uppercase tracking-widest text-center animate-in fade-in slide-in-from-top-2">
            {errorMessage}
          </div>
        )}

        {currentView === View.HOME && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="text-center mb-10">
              <p className="text-gray-500 uppercase tracking-[0.3em] text-xs font-bold mb-2">
                Automotive Community
              </p>
              <h2 className="text-xl md:text-2xl text-light-gray font-light max-w-xl mx-auto leading-relaxed">
                Il punto di riferimento per la passione <span className="text-brick-red font-semibold">automotive</span> nel Nord Italia.
              </h2>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-6 animate-in fade-in duration-500 max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red">CARSPOTTING</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            {user.isLoggedIn ? (
              <div className="bg-panel-gray border border-gray-800 p-6 mb-10">
                <div className="mb-6 flex flex-col items-center justify-center border-2 border-dashed border-gray-800 bg-black/20 p-4 min-h-[200px] hover:border-brick-red/50 transition-colors group relative overflow-hidden rounded-sm">
                  {previewUrl ? (
                    <div className="relative w-full h-full flex items-center justify-center bg-black">
                      <img 
                        src={previewUrl} 
                        alt="Preview" 
                        className="max-w-full max-h-[400px] object-contain shadow-2xl" 
                      />
                      <button 
                        type="button"
                        onClick={(e) => { 
                          e.stopPropagation();
                          setPreviewUrl(null); 
                          setImageBase64(null); 
                          setScannedCarModel(''); 
                        }}
                        className="absolute top-4 right-4 bg-black/80 p-3 hover:bg-brick-red transition-all border border-white/10"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                      </button>
                    </div>
                  ) : (
                    <button 
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                      disabled={isAnalyzing}
                      className="flex flex-col items-center gap-4 py-8 w-full"
                    >
                      <div className="p-5 bg-gray-900 rounded-full group-hover:bg-brick-red/10 border border-gray-800 group-hover:border-brick-red/30 transition-all">
                        <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
                      </div>
                      <div className="text-center">
                        <span className="block text-[11px] font-bold uppercase tracking-[0.4em] text-gray-500 group-hover:text-white transition-colors">Scatta o Scegli Foto</span>
                        <span className="block text-[9px] text-gray-600 uppercase tracking-widest mt-1">Obbligatorio per lo spot</span>
                      </div>
                    </button>
                  )}

                  {isAnalyzing && (
                    <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center backdrop-blur-md z-10">
                       <svg className="animate-spin h-10 w-10 text-brick-red mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                        </svg>
                        <p className="text-[10px] font-bold text-white uppercase tracking-[0.3em]">IA sta analizzando la carrozzeria...</p>
                    </div>
                  )}

                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*" 
                    capture="environment"
                    onChange={handleFileChange} 
                  />
                </div>

                <form onSubmit={handleAddSpot} className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <input 
                    name="car_model" 
                    placeholder="Modello Auto (es. Porsche 911)" 
                    value={scannedCarModel}
                    onChange={(e) => setScannedCarModel(e.target.value)}
                    className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red transition-all" 
                    required 
                  />
                  <button 
                    type="button"
                    className="bg-black border border-gray-800 p-3 text-sm text-gray-500 flex items-center justify-between hover:border-gray-600 transition-all group"
                  >
                    <span>Posizione Automatica</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-brick-red group-hover:scale-110 transition-transform"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                  </button>
                  <button 
                    type="submit" 
                    disabled={!imageBase64 || isAnalyzing}
                    className={`bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3 hover:bg-brick-red/80 transition-all ${(!imageBase64 || isAnalyzing) ? 'opacity-30 cursor-not-allowed grayscale' : ''}`}
                  >
                    Invia Segnalazione
                  </button>
                </form>
              </div>
            ) : (
              <div className="bg-panel-gray border border-gray-800 p-4 mb-10 text-center">
                <p className="text-xs text-gray-500 uppercase tracking-widest">Accedi per segnalare un avvistamento</p>
              </div>
