            <div className="space-y-6">
              {loading ? (
                <div className="space-y-4">
                  {[1,2,3].map(i => <div key={i} className="h-24 bg-panel-gray/50 animate-pulse border border-gray-800"></div>)}
                </div>
              ) : spots.length === 0 ? (
                <p className="text-center py-10 text-gray-600 italic">Nessun avvistamento recente.</p>
              ) : (
                spots.map(spot => (
                  <div key={spot.id} className="bg-panel-gray border border-gray-800 overflow-hidden flex flex-col md:flex-row group hover:border-brick-red/30 transition-all duration-500">
                    {spot.image_data && (
                      <div className="w-full md:w-48 aspect-video md:aspect-square bg-black overflow-hidden border-b md:border-b-0 md:border-r border-gray-800">
                        <img src={spot.image_data} alt={spot.car_model} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                      </div>
                    )}
                    <div className="p-5 flex-1 flex justify-between items-center">
                      <div>
                        <h3 className="text-xl font-bold text-white uppercase tracking-tight mb-1">{spot.car_model}</h3>
                        <div className="flex items-center gap-2 text-gray-500">
                           <svg xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-brick-red"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                           <p className="text-[10px] uppercase tracking-widest">{spot.location || "Nord Italia"}</p>
                        </div>
