                      <div className="text-right">
                        <p className="text-[9px] text-gray-600 uppercase mb-1">Spotter</p>
                        <p className="text-xs font-bold text-brick-red uppercase bg-brick-red/5 px-3 py-1 border border-brick-red/20">{spot.spotted_by}</p>
                      </div>
