import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View } from './types';
import { db } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<{ isLoggedIn: boolean; username?: string }>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [scannedCarModel, setScannedCarModel] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session) {
      setUser({ isLoggedIn: true, username: session.username });
    }
    loadData();

    // Pulizia degli ObjectURL per evitare perdite di memoria
    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  const loadData = async () => {
    setLoading(true);
    setErrorMessage(null);
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
    } catch (err: any) {
      setErrorMessage("Errore nel caricamento dei dati.");
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (username: string) => {
    db.auth.login(username);
    setUser({ isLoggedIn: true, username });
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    // 1. Mostra l'anteprima immediatamente usando ObjectURL
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);
    setIsAnalyzing(true);
    setErrorMessage(null);

    // 2. Leggi il file come Base64 per l'AI e per il salvataggio
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const result = reader.result as string;
        setImageBase64(result);

        const mimeTypeMatch = result.match(/^data:(image\/[a-z]+);base64,/);
        const mimeType = mimeTypeMatch ? mimeTypeMatch[1] : (file.type || 'image/jpeg');
        const base64Data = result.split(',')[1];

        const carModel = await identifyCarFromImage(base64Data, mimeType);

        if (carModel === 'Sconosciuta') {
          setScannedCarModel('');
        } else {
          setScannedCarModel(carModel);
        }
      } catch (err: any) {
        console.error("Errore analisi AI:", err);
        setErrorMessage("L'AI non ha risposto, inserisci il modello manualmente.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.onerror = () => {
      setErrorMessage("Errore nel caricamento del file.");
      setIsAnalyzing(false);
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!imageBase64) {
      alert("Devi allegare una foto!");
      return;
    }

    const formData = new FormData(e.currentTarget);
    const newSpot = {
      car_model: (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta",
      location: "Nord Italia (Posizione Rilevata)",
      spotted_by: user.username || 'Anonimo',
      image_data: imageBase64
    };

    try {
      await db.spots.create(newSpot);
      setScannedCarModel('');
      setPreviewUrl(null);
      setImageBase64(null);
      loadData();
      (e.target as HTMLFormElement).reset();
    } catch (err: any) {
      alert("Errore salvataggio: " + err.message);
    }
  };

  const handleAddEvent = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const newEvent = {
      title: formData.get('title') as string,
      date: formData.get('date') as string,
      location: formData.get('location') as string,
      description: formData.get('description') as string,
    };
    try {
      await db.events.create(newEvent);
      loadData();
      (e.target as HTMLFormElement).reset();
    } catch (err: any) {
      alert("Errore salvataggio evento.");
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white pb-20">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => setCurrentView(View.HOME)}
      />

      <main className="pt-24 px-4 md:px-8 max-w-7xl mx-auto">
        {errorMessage && (
          <div className="mb-6 bg-brick-red/20 border border-brick-red/50 p-4 text-brick-red text-xs font-bold uppercase tracking-widest text-center">
            {errorMessage}
          </div>
        )}

        {currentView === View.HOME && (
          <div className="animate-in fade-in duration-700">
            <div className="text-center mb-10">
              <p className="text-gray-500 uppercase tracking-[0.3em] text-[10px] font-bold mb-2">Automotive Community</p>
              <h2 className="text-xl md:text-2xl text-light-gray font-light max-w-xl mx-auto leading-relaxed">
                Il punto di riferimento per la passione <span className="text-brick-red font-semibold">automotive</span> nel Nord Italia.
              </h2>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-6 animate-in fade-in max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red">CARSPOTTING</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            {user.isLoggedIn ? (
              <div className="bg-panel-gray border border-gray-800 p-6 mb-10">
                <div className="mb-6">
                  {previewUrl ? (
                    <div className="relative w-full bg-black border border-gray-800 rounded-sm overflow-hidden flex items-center justify-center min-h-[250px] max-h-[500px]">
                      <img 
                        src={previewUrl} 
                        alt="Preview Spot" 
                        className="max-w-full max-h-[500px] object-contain block"
                        onLoad={() => console.log("Preview loaded")}
                      />
                      <button 
                        type="button"
                        onClick={() => { setPreviewUrl(null); setImageBase64(null); setScannedCarModel(''); }}
                        className="absolute top-4 right-4 bg-brick-red p-2 hover:bg-brick-red/80 transition-all text-white shadow-xl"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                      </button>
                      {isAnalyzing && (
                        <div className="absolute inset-0 bg-black/70 backdrop-blur-sm flex flex-col items-center justify-center">
                          <svg className="animate-spin h-10 w-10 text-brick-red mb-3" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"></path></svg>
                          <span className="text-[10px] font-bold uppercase tracking-widest text-white">Analisi IA in corso...</span>
                        </div>
                      )}
                    </div>
                  ) : (
                    <button 
                      type="button"
                      onClick={() => fileInputRef.current?.click()}
                      className="w-full h-48 border-2 border-dashed border-gray-800 hover:border-brick-red/50 hover:bg-white/5 transition-all flex flex-col items-center justify-center gap-4 group"
                    >
                      <div className="p-4 bg-gray-900 rounded-full group-hover:scale-110 transition-transform">
                        <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
                      </div>
                      <span className="text-[10px] font-bold uppercase tracking-[0.4em] text-gray-500">Foto Spot Obbligatoria</span>
                    </button>
                  )}
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" capture="environment" onChange={handleFileChange} />
                </div>

                <form onSubmit={handleAddSpot} className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <input 
                    name="car_model" 
                    placeholder="Modello Auto (Rilevato o Manuale)" 
                    value={scannedCarModel}
                    onChange={(e) => setScannedCarModel(e.target.value)}
                    className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red transition-all" 
                    required 
                  />
                  <button 
                    type="button"
                    className="bg-black border border-gray-800 p-3 text-sm text-gray-500 flex items-center justify-between hover:border-gray-600 transition-all cursor-default"
                  >
                    <span>Posizione Automatica</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                  </button>
                  <button 
                    type="submit" 
                    disabled={!imageBase64 || isAnalyzing}
                    className={`bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3 hover:bg-brick-red/80 transition-all ${(!imageBase64 || isAnalyzing) ? 'opacity-30 cursor-not-allowed' : ''}`}
                  >
                    Invia Segnalazione
                  </button>
                </form>
              </div>
            ) : (
              <div className="bg-panel-gray border border-gray-800 p-4 mb-10 text-center">
                <p className="text-xs text-gray-500 uppercase tracking-widest">Accedi per segnalare un avvistamento</p>
              </div>
            )}

            <div className="space-y-6">
              {loading ? (
                <div className="space-y-4">
                  {[1,2,3].map(i => <div key={i} className="h-24 bg-panel-gray/50 animate-pulse border border-gray-800"></div>)}
                </div>
              ) : spots.length === 0 ? (
                <p className="text-center py-10 text-gray-600 italic">Nessun avvistamento recente.</p>
              ) : (
                spots.map(spot => (
                  <div key={spot.id} className="bg-panel-gray border border-gray-800 overflow-hidden flex flex-col md:flex-row group hover:border-brick-red/30 transition-all duration-300">
                    {spot.image_data && (
                      <div className="w-full md:w-48 aspect-video md:aspect-square bg-black overflow-hidden border-b md:border-b-0 md:border-r border-gray-800">
                        <img src={spot.image_data} alt={spot.car_model} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" />
                      </div>
                    )}
                    <div className="p-5 flex-1 flex justify-between items-center">
                      <div>
                        <h3 className="text-xl font-bold text-white uppercase tracking-tight mb-1">{spot.car_model}</h3>
                        <p className="text-[10px] text-gray-500 uppercase tracking-[0.2em]">{spot.location || "Nord Italia"}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[9px] text-gray-600 uppercase mb-1">Spotter</p>
                        <p className="text-xs font-bold text-brick-red uppercase">{spot.spotted_by}</p>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-6 animate-in fade-in max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red">EVENTI</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            {user.isLoggedIn ? (
              <form onSubmit={handleAddEvent} className="bg-panel-gray border border-gray-800 p-6 mb-10 space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input name="title" placeholder="Nome dell'Evento" className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red" required />
                  <input name="date" type="date" className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red" required />
                </div>
                <input name="location" placeholder="Località" className="bg-black border border-gray-800 p-3 text-sm w-full outline-none focus:border-brick-red" required />
                <textarea name="description" placeholder="Descrizione..." className="bg-black border border-gray-800 p-3 text-sm w-full h-20 outline-none focus:border-brick-red" />
                <button type="submit" className="w-full bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3 hover:bg-brick-red/80 transition-colors">Aggiungi Evento</button>
