                  </button>
                  <button 
                    type="submit" 
                    disabled={!imageBase64 || isAnalyzing}
                    className={`bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3 hover:bg-brick-red/80 transition-all ${(!imageBase64 || isAnalyzing) ? 'opacity-30 cursor-not-allowed' : 'shadow-[0_0_15px_rgba(176,58,46,0.3)]'}`}
                  >
                    Invia Segnalazione
                  </button>
                </form>
              </div>
            ) : (
              <div className="bg-panel-gray border border-gray-800 p-8 mb-10 text-center">
                <p className="text-[10px] text-gray-500 uppercase tracking-[0.4em]">Accedi per partecipare alla community di carspotting</p>
