            <div className="space-y-6">
              <h3 className="text-xs font-bold text-gray-500 uppercase tracking-[0.3em] border-l-2 border-brick-red pl-3">Avvistamenti Recenti</h3>
              {loading ? (
                <div className="space-y-4">
                  {[1,2,3].map(i => <div key={i} className="h-28 bg-panel-gray/50 animate-pulse border border-gray-900"></div>)}
                </div>
              ) : spots.length === 0 ? (
                <p className="text-center py-16 text-gray-600 italic text-sm">Nessuna segnalazione presente.</p>
              ) : (
                spots.map(spot => (
                  <div key={spot.id} className="bg-panel-gray border border-gray-800 overflow-hidden flex flex-col md:flex-row group hover:border-brick-red/40 transition-all duration-500">
                    {spot.image_data && (
