                          <p className="text-xs font-bold text-brick-red uppercase bg-brick-red/5 px-2 py-1 border border-brick-red/10">{spot.spotted_by}</p>
                        </div>
                      </div>
                      <div className="mt-4 text-[9px] text-gray-700 uppercase tracking-widest flex items-center justify-between">
                        <span>{new Date(spot.created_at).toLocaleDateString()}</span>
                        <span className="group-hover:text-brick-red transition-colors">ID: #{spot.id.toString().slice(0,6)}</span>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-6 animate-in fade-in max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
