                <textarea name="description" placeholder="Informazioni sull'evento..." className="bg-black border border-gray-800 p-3 text-sm w-full h-24 outline-none focus:border-brick-red text-white resize-none" />
                <button type="submit" className="w-full bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-4 hover:bg-brick-red/80 transition-all active:scale-[0.99]">Pubblica Evento</button>
