              {loading ? (
                <div className="space-y-4">
                   {[1,2].map(i => <div key={i} className="h-32 bg-panel-gray/50 animate-pulse border border-gray-900"></div>)}
                </div>
              ) : events.length === 0 ? (
                <p className="text-center py-16 text-gray-600 italic text-sm">Nessun evento in programma al momento.</p>
