export default App;

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View } from './types';
import { db } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<{ isLoggedIn: boolean; username?: string }>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [scannedCarModel, setScannedCarModel] = useState('');
  const [imageBase64, setImageBase64] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session) {
      setUser({ isLoggedIn: true, username: session.username });
    }
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    setErrorMessage(null);
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
    } catch (err: any) {
      setErrorMessage("Errore caricamento dati.");
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (username: string) => {
    db.auth.login(username);
    setUser({ isLoggedIn: true, username });
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorMessage(null);
    setIsAnalyzing(true);

    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        // Disegna su Canvas per l'anteprima (molto più affidabile)
        const canvas = canvasRef.current;
        if (canvas) {
          const ctx = canvas.getContext('2d');
          if (ctx) {
            // Calcola proporzioni
            const maxWidth = 800;
            const scale = Math.min(maxWidth / img.width, 1);
            canvas.width = img.width * scale;
            canvas.height = img.height * scale;
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
          }
        }

        // Prepara base64 per IA e DB
        const base64String = event.target?.result as string;
        setImageBase64(base64String);

        // Avvia analisi IA
        processIA(base64String, file.type);
      };
      img.src = event.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  const processIA = async (base64: string, type: string) => {
    try {
      const mimeType = type || 'image/jpeg';
      const base64Data = base64.split(',')[1];
      const carModel = await identifyCarFromImage(base64Data, mimeType);
      setScannedCarModel(carModel !== 'Sconosciuta' ? carModel : '');
    } catch (err) {
      console.error(err);
      setErrorMessage("IA non disponibile. Inserisci il modello manualmente.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!imageBase64) {
      alert("Carica una foto per lo spot!");
      return;
    }

    const formData = new FormData(e.currentTarget);
    const newSpot = {
      car_model: (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta",
      location: "Nord Italia (Rilevata)",
      spotted_by: user.username || 'Anonimo',
      image_data: imageBase64
    };

    try {
      await db.spots.create(newSpot);
      setImageBase64(null);
      setScannedCarModel('');
      loadData();
    } catch (err: any) {
      alert("Errore salvataggio spot.");
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => setCurrentView(View.HOME)}
      />

      <main className="pt-24 px-4 md:px-8 max-w-7xl mx-auto">
        {currentView === View.HOME && (
          <div className="animate-in fade-in duration-700">
            <div className="text-center mb-10">
              <p className="text-gray-500 uppercase tracking-[0.3em] text-[10px] font-bold mb-2">Automotive Community</p>
              <h2 className="text-xl md:text-2xl text-light-gray font-light max-w-xl mx-auto leading-relaxed">
                Il punto di riferimento per la passione <span className="text-brick-red font-semibold">automotive</span> nel Nord Italia.
              </h2>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-6 animate-in fade-in max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red">CARSPOTTING</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            {user.isLoggedIn ? (
              <div className="bg-panel-gray border border-gray-800 p-6 mb-10">
                <div className="mb-6">
                  <div className={`relative w-full min-h-[250px] bg-black border border-gray-800 flex flex-col items-center justify-center overflow-hidden transition-all duration-500 ${isAnalyzing ? 'border-brick-red/50 shadow-[0_0_20px_rgba(176,58,46,0.1)]' : ''}`}>

                    {/* Canvas Preview - Il cuore del fix */}
                    <canvas 
                      ref={canvasRef} 
                      className={`max-w-full h-auto max-h-[500px] ${!imageBase64 ? 'hidden' : 'block'}`}
                    />

                    {!imageBase64 && (
                      <button 
                        type="button"
                        onClick={() => fileInputRef.current?.click()}
                        className="flex flex-col items-center gap-4 group py-10"
                      >
                        <div className="p-5 bg-gray-900 rounded-full group-hover:bg-brick-red/10 transition-colors">
                          <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="1.5"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
                        </div>
                        <span className="text-[10px] font-bold uppercase tracking-[0.4em] text-gray-500 group-hover:text-white">Carica Foto Spot</span>
                      </button>
                    )}

                    {imageBase64 && (
                      <button 
                        type="button"
                        onClick={() => { setImageBase64(null); setScannedCarModel(''); }}
                        className="absolute top-4 right-4 bg-brick-red p-2 hover:bg-brick-red/80 transition-all text-white z-20"
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                      </button>
                    )}

                    {isAnalyzing && (
                      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-10">
                        <div className="w-10 h-10 border-2 border-brick-red/20 border-t-brick-red rounded-full animate-spin mb-3"></div>
                        <span className="text-[9px] font-bold uppercase tracking-[0.3em] text-white">Analisi Modello...</span>
                      </div>
                    )}
                  </div>

                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                </div>

                <form onSubmit={handleAddSpot} className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <input 
                    name="car_model" 
                    placeholder="Marca e Modello" 
                    value={scannedCarModel}
                    onChange={(e) => setScannedCarModel(e.target.value)}
                    className="bg-black border border-gray-800 p-3 text-sm outline-none focus:border-brick-red text-white" 
                    required 
                  />
                  <div className="bg-black border border-gray-800 p-3 text-sm text-gray-600 flex items-center justify-between">
                    <span>Posizione Automatica</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                  </div>
                  <button 
                    type="submit" 
                    disabled={!imageBase64 || isAnalyzing}
                    className={`bg-brick-red text-white font-bold text-xs uppercase tracking-widest py-3 hover:bg-brick-red/80 transition-all ${(!imageBase64 || isAnalyzing) ? 'opacity-30 cursor-not-allowed' : ''}`}
                  >
                    Invia Spot
                  </button>
                </form>
              </div>
            ) : (
              <div className="bg-panel-gray border border-gray-800 p-10 text-center mb-10">
                <p className="text-[10px] text-gray-500 uppercase tracking-widest">Accedi per condividere i tuoi avvistamenti</p>
              </div>
            )}

            <div className="space-y-6">
              {spots.map(spot => (
                <div key={spot.id} className="bg-panel-gray border border-gray-800 overflow-hidden flex flex-col md:flex-row group transition-all duration-300">
                  <div className="w-full md:w-56 aspect-video md:aspect-square bg-black overflow-hidden border-b md:border-b-0 md:border-r border-gray-800">
                    <img src={spot.image_data} alt={spot.car_model} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                  </div>
                  <div className="p-6 flex-1 flex flex-col justify-between">
                    <div className="flex justify-between items-start">
                      <div>
                        <h3 className="text-2xl font-bold text-white uppercase tracking-tighter mb-1">{spot.car_model}</h3>
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest">{spot.location}</p>
                      </div>
                      <div className="text-right">
                        <p className="text-[8px] text-gray-600 uppercase mb-1">Spotter</p>
                        <p className="text-xs font-bold text-brick-red uppercase">{spot.spotted_by}</p>
                      </div>
                    </div>
                    <div className="mt-4 text-[9px] text-gray-700 uppercase tracking-widest">
                      {new Date(spot.created_at).toLocaleDateString()}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-6 animate-in fade-in max-w-4xl mx-auto">
             <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red uppercase">EVENTI</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest">Chiudi</button>
            </div>

            <div className="grid grid-cols-1 gap-6">
              {events.map(event => (
                <div key={event.id} className="bg-panel-gray border border-gray-800 p-6 hover:border-brick-red/30 transition-all group">
                  <div className="flex flex-col md:flex-row justify-between gap-4 mb-4">
                    <div>
                      <h3 className="text-2xl font-bold text-white uppercase tracking-tighter group-hover:text-brick-red transition-colors">{event.title}</h3>
                      <p className="text-[10px] text-gray-400 uppercase tracking-widest mt-1">{event.location}</p>
                    </div>
                    <div className="bg-brick-red text-white font-brand text-sm px-4 py-2 self-start">
                      {new Date(event.date).toLocaleDateString()}
                    </div>
                  </div>
                  <p className="text-sm text-gray-500 leading-relaxed border-t border-gray-800 pt-4">{event.description}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </main>

      {isAuthModalOpen && <AuthModal onClose={() => setIsAuthModalOpen(false)} onLogin={handleLogin} />}

      <footer className="fixed bottom-0 left-0 right-0 py-4 bg-black border-t border-gray-900 text-center text-[9px] text-gray-700 z-40 uppercase tracking-[0.5em]">
        RADUNINORDITALIA &copy; {new Date().getFullYear()}
      </footer>
    </div>
  );
};

