import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View } from './types';
import { db } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<{ isLoggedIn: boolean; username?: string }>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [scannedCarModel, setScannedCarModel] = useState('');
  const [localPreview, setLocalPreview] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session) {
      setUser({ isLoggedIn: true, username: session.username });
    }
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
    } catch (err) {
      console.error("Errore caricamento:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleLogin = (username: string) => {
    db.auth.login(username);
    setUser({ isLoggedIn: true, username });
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorMessage(null);
    setScannedCarModel('');
    setIsAnalyzing(true);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const base64String = event.target?.result as string;

      // Metodo Background: impostiamo subito lo stato locale
      setLocalPreview(base64String);

      try {
        const mimeType = file.type || 'image/jpeg';
        const base64Data = base64String.split(',')[1];

        // Chiamata all'IA
        const carModel = await identifyCarFromImage(base64Data, mimeType);
        setScannedCarModel(carModel !== 'Sconosciuta' ? carModel : '');
      } catch (err) {
        console.error("IA Error:", err);
        setErrorMessage("L'IA non ha risposto, inserisci il modello manualmente.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!localPreview) {
      alert("Seleziona prima una foto!");
      return;
    }

    const formData = new FormData(e.currentTarget);
    const carModelInput = (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta";

    const newSpot = {
      car_model: carModelInput,
      location: "Nord Italia",
      spotted_by: user.username || 'Anonimo',
      image_data: localPreview
    };

    try {
      await db.spots.create(newSpot);
      setLocalPreview(null);
      setScannedCarModel('');
      loadData(); // Aggiorna la lista globale
    } catch (err) {
      alert("Errore durante il salvataggio.");
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans pb-20">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => setCurrentView(View.HOME)}
      />

      <main className="pt-24 px-4 md:px-8 max-w-7xl mx-auto">
        {currentView === View.HOME && (
          <div className="animate-in fade-in duration-700">
            <div className="text-center mb-10">
              <p className="text-gray-500 uppercase tracking-[0.3em] text-[10px] font-bold mb-2">Automotive Community</p>
              <h2 className="text-xl md:text-2xl text-light-gray font-light max-w-xl mx-auto leading-relaxed">
                Il punto di riferimento per la passione <span className="text-brick-red font-semibold">automotive</span> nel Nord Italia.
              </h2>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-6 animate-in fade-in max-w-4xl mx-auto">
            <div className="flex justify-between items-end mb-8 border-b border-gray-800 pb-4">
              <h2 className="text-3xl font-brand text-brick-red uppercase">CARSPOTTING</h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-500 hover:text-white uppercase tracking-widest p-2">Chiudi</button>
            </div>

            {user.isLoggedIn ? (
              <div className="bg-panel-gray border border-gray-800 p-6 mb-12">
                <div className="mb-6">
                  {/* CONTENITORE ANTEPRIMA - CAMBIATO IN BACKGROUND DIV */}
                  <div 
                    className={`relative w-full h-[400px] md:h-[500px] bg-black border-2 transition-all duration-500 overflow-hidden flex flex-col items-center justify-center rounded-sm ${isAnalyzing ? 'border-brick-red animate-pulse' : 'border-gray-800'}`}
                    style={localPreview ? {
                      backgroundImage: `url(${localPreview})`,
                      backgroundPosition: 'center',
                      backgroundSize: 'contain',
                      backgroundRepeat: 'no-repeat'
                    } : {}}
                  >
                    {!localPreview ? (
                      <button 
                        type="button"
                        onClick={() => fileInputRef.current?.click()}
                        className="flex flex-col items-center gap-6 group"
                      >
                        <div className="p-8 bg-gray-900/50 rounded-full border border-gray-800 group-hover:border-brick-red/50 transition-all">
                          <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="1.5"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
                        </div>
                        <span className="text-[11px] font-bold uppercase tracking-[0.5em] text-gray-500 group-hover:text-white">Carica Foto Spot</span>
                      </button>
                    ) : (
                      <>
                        {/* Overlay scuro solo se l'IA sta analizzando */}
                        {isAnalyzing && (
                          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center z-10">
                            <div className="w-12 h-12 border-4 border-brick-red/20 border-t-brick-red rounded-full animate-spin mb-4"></div>
                            <span className="text-[10px] font-bold uppercase tracking-widest text-white">L'IA sta identificando l'auto...</span>
                          </div>
                        )}
                        {/* Tasto Cancella sempre visibile se c'è anteprima */}
                        <button 
                          type="button"
                          onClick={() => { setLocalPreview(null); setScannedCarModel(''); }}
                          className="absolute top-4 right-4 bg-brick-red text-white p-3 hover:scale-110 transition-transform z-20 shadow-2xl"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                        </button>
                      </>
                    )}
                  </div>

                  {errorMessage && (
                    <p className="mt-4 text-brick-red text-[10px] font-bold uppercase tracking-widest text-center">{errorMessage}</p>
                  )}

                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
