                      onChange={(e) => setScannedCarModel(e.target.value)}
                      className="w-full bg-black border border-gray-800 p-4 text-sm outline-none focus:border-brick-red text-white transition-all" 
                      required 
                    />
                    {scannedCarModel && !isAnalyzing && (
                      <span className="absolute -top-2 left-3 bg-panel-gray px-2 text-[8px] font-bold text-brick-red uppercase tracking-widest border border-gray-800">Suggerito dall'IA</span>
                    )}
                  </div>
                  <div className="bg-black border border-gray-800 p-4 text-sm text-gray-500 flex items-center justify-between uppercase tracking-tighter">
                    <span className="text-[10px] font-bold">Località: Nord Italia</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                  </div>
                  <button 
                    type="submit" 
                    disabled={!localPreview || isAnalyzing}
                    className={`bg-brick-red text-white font-bold text-xs uppercase tracking-[0.2em] py-4 hover:bg-brick-red/80 transition-all ${(!localPreview || isAnalyzing) ? 'opacity-30 cursor-not-allowed' : 'shadow-xl shadow-brick-red/20'}`}
                  >
                    Pubblica Avvistamento
                  </button>
                </form>
              </div>
            ) : (
              <div className="bg-panel-gray border border-gray-800 p-16 text-center mb-10">
                <p className="text-[11px] text-gray-500 uppercase tracking-[0.5em] mb-6">Effettua l'accesso per condividere i tuoi spot</p>
