import React, { useState } from 'react';
import { db } from '../services/db';

interface AuthModalProps {
  onClose: () => void;
  onLogin: (userData: any) => void;
}

type AuthMode = 'login' | 'register' | 'organizer';

const AuthModal: React.FC<AuthModalProps> = ({ onClose, onLogin }) => {
  const [mode, setMode] = useState<AuthMode>('login');
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    identifier: '',
    username: '',
    email: '',
    password: '',
    confirmPassword: '',
    orgName: '',
    phoneNumber: ''
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    setError('');
    setSuccess('');
  };

  const handleResetDatabase = async () => {
    if (!window.confirm("ATTENZIONE: Stai per eliminare TUTTI gli account dal database. Questa operazione è irreversibile. Continuare?")) return;
    setIsLoading(true);
    try {
      await db.users.dangerouslyClearAll();
      setSuccess("Database utenti ripulito con successo!");
      setMode('register');
    } catch (err) {
      setError("Errore durante il reset.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');

    try {
      if (mode === 'login') {
        const user = await db.users.findByUsername(formData.identifier);
        if (user && user.password === formData.password) {
          onLogin(user);
        } else {
          setError('Credenziali non valide. Verifica username e password.');
        }
      } else if (mode === 'register' || mode === 'organizer') {
        const nameToUse = mode === 'register' ? formData.username : formData.orgName;

        if (formData.password !== formData.confirmPassword) {
          setError('Le password non coincidono');
          setIsLoading(false);
          return;
