/**
 * --- CONFIGURAZIONE CAPO DI TUTTO ---
 */
const MASTER_USERNAME = 'TIA_258'; 

const STORAGE_KEYS = {
  SESSION: 'rni_session'
};

export const db = {
  users: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('users').select('*').order('username');
      if (error) throw error;
      return data || [];
    },
    dangerouslyClearAll: async () => {
      if (!supabase) return false;
      // Per cancellare tutto su Supabase serve un filtro che colpisca tutte le righe
      const { error } = await supabase.from('users').delete().neq('id', '00000000-0000-0000-0000-000000000000');
      if (error) throw error;
      return true;
    },
    create: async (userData: any) => {
      if (!supabase) return null;

      const isMaster = userData.username?.toLowerCase() === MASTER_USERNAME.toLowerCase();

      if (isMaster) {
        const { data: existing } = await supabase
          .from('users')
          .select('id')
          .eq('username', userData.username)
          .maybeSingle();

        if (existing) {
          const { data, error } = await supabase
            .from('users')
            .update({ 
              password: userData.password, 
              email: userData.email, 
              role: 'admin' 
            })
            .eq('id', existing.id)
            .select();
          if (error) throw error;
          return data[0];
        }
      }

      const { count } = await supabase.from('users').select('*', { count: 'exact', head: true });
      let role = 'user';
      if (count === 0 || isMaster) {
        role = 'admin';
      }

      const { data, error } = await supabase.from('users').insert([
        { 
          username: userData.username, 
          email: userData.email, 
          password: userData.password,
          role: role
        }
      ]).select();

      if (error) throw error;
      return data[0];
    },
    updateRole: async (userId: string, newRole: string) => {
      if (!supabase) return;
      const { data: user } = await supabase.from('users').select('username').eq('id', userId).single();
      if (user && user.username.toLowerCase() === MASTER_USERNAME.toLowerCase() && newRole !== 'admin') {
        throw new Error("Non puoi declassare il Capo di Tutto.");
      }
      const { error } = await supabase.from('users').update({ role: newRole }).eq('id', userId);
      if (error) throw error;
    },
    findByUsername: async (identifier: string) => {
      if (!supabase) return null;

      try {
        // Tentativo 1: Query OR (può fallire se identifier ha caratteri speciali non escapati)
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .or(`username.eq.${identifier},email.eq.${identifier}`)
          .maybeSingle();

        if (!error && data) {
          return await checkMasterPromotion(data);
        }

        // Tentativo 2: Fallback sicuro per username
        const { data: dataByUsername } = await supabase
          .from('users')
          .select('*')
          .eq('username', identifier)
          .maybeSingle();

        if (dataByUsername) return await checkMasterPromotion(dataByUsername);

        // Tentativo 3: Fallback sicuro per email
        const { data: dataByEmail } = await supabase
          .from('users')
          .select('*')
          .eq('email', identifier)
          .maybeSingle();

        if (dataByEmail) return await checkMasterPromotion(dataByEmail);

      } catch (e) {
        console.error("Errore ricerca utente:", e);
      }
      return null;
    }
  },

  events: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
      if (error) throw error;
      return data || [];
    },
    create: async (eventData: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('events').insert([eventData]).select();
      if (error) throw error;
      return data[0];
    }
  },

  spots: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      return data || [];
    },
    create: async (spotData: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('spots').insert([spotData]).select();
      if (error) throw error;
      return data[0];
    }
  },

  auth: {
    login: (userData: any) => {
      if (!userData) return null;
      const session = { 
        username: userData.username, 
        role: userData.role, 
        id: userData.id, 
        timestamp: Date.now() 
      };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      try {
        return session ? JSON.parse(session) : null;
      } catch {
        return null;
      }
    }
  }
};

async function checkMasterPromotion(user: any) {
  if (user && user.username.toLowerCase() === MASTER_USERNAME.toLowerCase() && user.role !== 'admin') {
    if (supabase) {
      await supabase.from('users').update({ role: 'admin' }).eq('id', user.id);
      user.role = 'admin';
    }
  }
  return user;
}

