/**
 * Utility per estrarre messaggi di errore puliti da Supabase
 */
const getCleanErrorMessage = (error: any): string => {
  if (typeof error === 'string') return error;
  if (error?.message) return error.message;
  if (error?.details) return error.details;
  return "Errore sconosciuto del database";
};

export const db = {
  users: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('users').select('*').order('username');
      if (error) throw new Error(getCleanErrorMessage(error));
      return data || [];
    },
    dangerouslyClearAll: async () => {
      if (!supabase) return false;
      // Elimina tutto basandosi su un filtro ID non nullo (funziona sia con UUID che con Integer)
      const { error } = await supabase.from('users').delete().not('id', 'is', null);
      if (error) {
        console.error("Errore reset:", error);
        throw new Error("Impossibile pulire il database: " + getCleanErrorMessage(error));
      }
      return true;
    },
    create: async (userData: any) => {
      if (!supabase) return null;

      const isMaster = userData.username?.toLowerCase() === MASTER_USERNAME.toLowerCase();

      try {
        // Se è il Master, proviamo prima a vedere se esiste per aggiornarlo
        if (isMaster) {
          const { data: existing } = await supabase
            .from('users')
            .select('id')
            .eq('username', userData.username)
            .maybeSingle();

          if (existing) {
            const { data, error: updateError } = await supabase
              .from('users')
              .update({ 
                password: userData.password, 
                email: userData.email, 
                role: 'admin' 
              })
              .eq('id', existing.id)
              .select();

            if (updateError) throw new Error(getCleanErrorMessage(updateError));
            return data[0];
          }
        }

        // Determina il ruolo
        let role = 'user';
        const { count, error: countError } = await supabase.from('users').select('*', { count: 'exact', head: true });
        if (!countError && (count === 0 || isMaster)) {
          role = 'admin';
        }

        // Inserimento
        const { data, error: insertError } = await supabase.from('users').insert([
          { 
            username: userData.username, 
            email: userData.email, 
            password: userData.password,
            role: role
          }
        ]).select();

        if (insertError) {
          // Se l'errore riguarda specificamente la colonna 'role', lo notifichiamo all'utente
          if (insertError.message.includes("role")) {
            throw new Error("La colonna 'role' non esiste nel database. Aggiungila su Supabase o disabilita RLS.");
          }
          throw new Error(getCleanErrorMessage(insertError));
        }
        return data ? data[0] : null;

      } catch (err: any) {
        throw new Error(getCleanErrorMessage(err));
      }
    },
    updateRole: async (userId: string, newRole: string) => {
      if (!supabase) return;
      const { data: user, error: getError } = await supabase.from('users').select('username').eq('id', userId).single();
      if (getError) throw new Error(getCleanErrorMessage(getError));

      if (user && user.username.toLowerCase() === MASTER_USERNAME.toLowerCase() && newRole !== 'admin') {
        throw new Error("Non puoi declassare l'account amministratore master.");
      }

      const { error: updateError } = await supabase.from('users').update({ role: newRole }).eq('id', userId);
      if (updateError) throw new Error(getCleanErrorMessage(updateError));
    },
    findByUsername: async (identifier: string) => {
      if (!supabase) return null;

      try {
        // Cerchiamo per username o email
        const { data, error } = await supabase
          .from('users')
          .select('*')
          .or(`username.eq."${identifier}",email.eq."${identifier}"`)
          .maybeSingle();

        if (error) {
          // Fallback se la query OR complessa fallisce per questioni di schema cache
          const { data: fbData } = await supabase.from('users').select('*').eq('username', identifier).maybeSingle();
          if (fbData) return await checkMasterPromotion(fbData);

          const { data: emData } = await supabase.from('users').select('*').eq('email', identifier).maybeSingle();
          return emData ? await checkMasterPromotion(emData) : null;
        }

        return data ? await checkMasterPromotion(data) : null;
      } catch (e) {
        return null;
      }
    }
  },

  events: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
      if (error) throw new Error(getCleanErrorMessage(error));
      return data || [];
    },
    create: async (eventData: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('events').insert([eventData]).select();
      if (error) throw new Error(getCleanErrorMessage(error));
      return data[0];
    }
  },

  spots: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
      if (error) throw new Error(getCleanErrorMessage(error));
      return data || [];
    },
    create: async (spotData: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('spots').insert([spotData]).select();
      if (error) throw new Error(getCleanErrorMessage(error));
      return data[0];
    }
  },

  auth: {
    login: (userData: any) => {
      if (!userData) return null;
      const session = { 
        username: userData.username, 
        role: userData.role, 
        id: userData.id, 
        timestamp: Date.now() 
      };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      try {
        return session ? JSON.parse(session) : null;
      } catch {
        return null;
      }
    }
  }
};

async function checkMasterPromotion(user: any) {
