              <>
                <InputField label="Username o Email" name="identifier" value={formData.identifier} onChange={handleInputChange} placeholder="Inserisci credenziali" disabled={isLoading} />
                <InputField label="Password" name="password" type="password" value={formData.password} onChange={handleInputChange} placeholder="••••••••" disabled={isLoading} />
              </>
            ) : (
              <>
                <InputField label="Username scelto" name="username" value={formData.username} onChange={handleInputChange} placeholder="Esempio: TIA_258" disabled={isLoading} />
                <InputField label="Email valida" name="email" type="email" value={formData.email} onChange={handleInputChange} placeholder="nome@esempio.it" disabled={isLoading} />
                <div className="grid grid-cols-2 gap-3">
                  <InputField label="Password" name="password" type="password" value={formData.password} onChange={handleInputChange} placeholder="••••" disabled={isLoading} />
                  <InputField label="Ripeti" name="confirmPassword" type="password" value={formData.confirmPassword} onChange={handleInputChange} placeholder="••••" disabled={isLoading} />
                </div>
              </>
            )}

            <button 
              type="submit"
              disabled={isLoading}
              className={`w-full bg-brick-red text-white py-4 font-bold hover:bg-brick-red/90 transition-all active:scale-[0.98] mt-4 tracking-[0.2em] text-sm flex items-center justify-center gap-2 ${isLoading ? 'opacity-70 cursor-wait' : ''}`}
            >
              {isLoading && (
                <svg className="animate-spin h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
              )}
              {mode === 'login' ? 'ACCEDI ORA' : 'CREA PROFILO'}
            </button>
          </form>

          {mode === 'register' && (
            <div className="mt-12 pt-6 border-t border-gray-900 flex flex-col items-center gap-4">
               <p className="text-[9px] text-gray-700 uppercase tracking-widest text-center">Gestione Database</p>
               <button 
                onClick={handleResetDatabase}
                type="button"
                disabled={isLoading}
                className="text-gray-800 hover:text-brick-red text-[8px] font-bold uppercase tracking-[0.4em] transition-colors border border-transparent hover:border-brick-red/20 px-4 py-2"
               >
                 [ Svuota Tabella Utenti ]
               </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const InputField = ({ label, type = 'text', ...props }: any) => {
  const [showPassword, setShowPassword] = useState(false);
  const isPassword = type === 'password';
  const inputType = isPassword ? (showPassword ? 'text' : 'password') : type;

  return (
    <div>
      <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em] mb-1.5">{label}</label>
      <div className="relative">
        <input 
          {...props}
          type={inputType}
          className="w-full bg-black border border-gray-800 p-3 pr-10 text-white focus:border-brick-red outline-none transition-colors text-sm placeholder:text-gray-700 disabled:opacity-50"
          required
        />
        {isPassword && (
          <button
            type="button"
            onClick={() => setShowPassword(!showPassword)}
            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-600 hover:text-brick-red transition-colors outline-none"
          >
            {showPassword ? (
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 9.9-1"></path></svg>
            )}
          </button>
        )}
      </div>
    </div>
  );
};

export default AuthModal;

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import { View, UserRole, User } from './types';
import { db } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [user, setUser] = useState<User>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [allUsers, setAllUsers] = useState<any[]>([]);

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [scannedCarModel, setScannedCarModel] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [base64ForAI, setBase64ForAI] = useState<string | null>(null);

  const [showEventForm, setShowEventForm] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session && session.username) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id
      });
    }
    loadData();

    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  const loadData = async () => {
    try {
      const [eventsData, spotsData] = await Promise.all([
        db.events.getAll(),
        db.spots.getAll()
      ]);
      setEvents(eventsData || []);
      setSpots(spotsData || []);
    } catch (err) {
      console.error("Errore caricamento dati:", err);
    }
  };

  const loadAllUsers = async () => {
    if (user.role !== UserRole.ADMIN) return;
    try {
      const usersData = await db.users.getAll();
      setAllUsers(usersData);
    } catch (err) {
      console.error("Errore caricamento utenti:", err);
    }
  };

  const handleUpdateUserRole = async (userId: string, newRole: UserRole) => {
    try {
      await db.users.updateRole(userId, newRole);
      setAllUsers(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
    } catch (err) {
      alert("Errore nell'aggiornamento ruolo.");
    }
  };

  const handleLogin = (userData: any) => {
    if (!userData) return;
    const session = db.auth.login(userData);
    if (session) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id 
      });
    }
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorMessage(null);
    setScannedCarModel('');
    setIsAnalyzing(true);

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const fullBase64 = event.target?.result as string;
      setBase64ForAI(fullBase64);

      try {
        const mimeType = file.type || 'image/jpeg';
        const base64Data = fullBase64.split(',')[1];
        const carModel = await identifyCarFromImage(base64Data, mimeType);
        if (carModel && carModel !== 'Sconosciuta') {
          setScannedCarModel(carModel);
        }
      } catch (err) {
        setErrorMessage("L'IA non è riuscita a identificare l'auto.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!base64ForAI || isSaving) return;

    setIsSaving(true);
    const formData = new FormData(e.currentTarget);
    const carModelInput = (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta";

    const newSpot = {
      car_model: carModelInput,
      location: "Nord Italia",
      spotted_by: user.username || 'Anonimo',
      image_data: base64ForAI,
      created_at: new Date().toISOString()
    };

    try {
      const savedSpot = await db.spots.create(newSpot);
      setSpots(prev => [savedSpot, ...prev]);
      setPreviewUrl(null);
      setBase64ForAI(null);
      setScannedCarModel('');
    } catch (err) {
      alert("Errore durante il salvataggio dello spot.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const eventData = {
      title: formData.get('title'),
      date: formData.get('date'),
      location: formData.get('location'),
      description: formData.get('description'),
      created_by: user.id
    };

    try {
      const newEvent = await db.events.create(eventData);
      setEvents(prev => [newEvent, ...prev].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()));
      setShowEventForm(false);
    } catch (err) {
      alert("Errore nella creazione dell'evento.");
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
        onLogout={handleLogout}
        user={user}
        onNavigateHome={() => {
          setCurrentView(View.HOME);
          setShowEventForm(false);
        }}
        onOpenAdmin={() => {
          setCurrentView(View.ADMIN_PANEL);
          loadAllUsers();
        }}
      />

      <main className="pt-24 pb-24 px-4 md:px-8 max-w-7xl mx-auto">
        {currentView === View.HOME && (
          <div className="animate-in fade-in zoom-in duration-500">
            <div className="text-center mb-12">
              <p className="text-brick-red uppercase tracking-[0.5em] text-[10px] font-bold mb-4">Official Community</p>
              <h2 className="text-2xl md:text-4xl text-white font-brand tracking-tighter mb-4">
                RADUNI NORD ITALIA
              </h2>
              <div className="h-1 w-20 bg-brick-red mx-auto mb-8"></div>
            </div>
            <Hero onSelectView={(view) => setCurrentView(view)} />
          </div>
        )}

        {currentView === View.ADMIN_PANEL && user.role === UserRole.ADMIN && (
          <div className="animate-in fade-in duration-500 max-w-6xl mx-auto">
            <div className="flex justify-between items-center mb-12 border-b border-gray-900 pb-6">
              <h2 className="text-4xl font-brand text-white italic tracking-tighter">ADMIN<span className="text-brick-red">PANEL</span></h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-600 hover:text-white uppercase tracking-widest border border-gray-800 px-4 py-2 transition-colors">Chiudi</button>
            </div>

            <div className="bg-panel-gray border border-gray-800 overflow-hidden shadow-2xl">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-black border-b border-gray-800">
                      <th className="p-6 text-[10px] font-bold uppercase tracking-widest text-gray-500">Utente</th>
                      <th className="p-6 text-[10px] font-bold uppercase tracking-widest text-gray-500">Email</th>
                      <th className="p-6 text-[10px] font-bold uppercase tracking-widest text-gray-500">Ruolo Attuale</th>
                      <th className="p-6 text-[10px] font-bold uppercase tracking-widest text-gray-500">Azioni Gestionali</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-900">
                    {allUsers.map(u => (
                      <tr key={u.id} className="hover:bg-black/50 transition-colors">
                        <td className="p-6">
                          <span className="text-white font-bold text-sm tracking-tight">{u.username}</span>
                          {u.username === user.username && <span className="ml-2 text-[8px] bg-brick-red text-white px-1.5 py-0.5 rounded">TU</span>}
                        </td>
                        <td className="p-6 text-gray-500 text-sm">{u.email}</td>
                        <td className="p-6">
                          <span className={`text-[9px] font-bold px-3 py-1 uppercase tracking-widest rounded-full border ${
                            u.role === 'admin' ? 'border-brick-red text-brick-red bg-brick-red/5' : 
                            u.role === 'organizer' ? 'border-blue-500 text-blue-500 bg-blue-500/5' : 
                            'border-gray-700 text-gray-500'
                          }`}>
                            {u.role}
                          </span>
                        </td>
                        <td className="p-6">
                          <div className="flex flex-wrap gap-2">
                            <button 
                              onClick={() => handleUpdateUserRole(u.id, UserRole.USER)}
                              className={`px-3 py-1 text-[9px] font-bold uppercase tracking-widest border transition-all ${u.role === 'user' ? 'border-gray-800 text-gray-700 cursor-not-allowed' : 'border-gray-700 text-gray-400 hover:text-white hover:border-white'}`}
                              disabled={u.role === 'user' || u.username === user.username}
                            >
                              User
                            </button>
                            <button 
                              onClick={() => handleUpdateUserRole(u.id, UserRole.ORGANIZER)}
                              className={`px-3 py-1 text-[9px] font-bold uppercase tracking-widest border transition-all ${u.role === 'organizer' ? 'border-gray-800 text-gray-700 cursor-not-allowed' : 'border-blue-900 text-blue-500 hover:bg-blue-500 hover:text-white'}`}
                              disabled={u.role === 'organizer'}
                            >
                              Organizer
                            </button>
                            {user.username === 'TIA_258' && u.username !== 'TIA_258' && (
                               <button 
                                onClick={() => handleUpdateUserRole(u.id, UserRole.ADMIN)}
                                className={`px-3 py-1 text-[9px] font-bold uppercase tracking-widest border transition-all ${u.role === 'admin' ? 'border-gray-800 text-gray-700 cursor-not-allowed' : 'border-brick-red text-brick-red hover:bg-brick-red hover:text-white'}`}
                                disabled={u.role === 'admin'}
                              >
                                Admin
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {currentView === View.CARSPOTTING && (
          <div className="py-4 animate-in fade-in duration-500 max-w-5xl mx-auto">
            <div className="flex justify-between items-center mb-12 border-b border-gray-900 pb-6">
              <h2 className="text-4xl font-brand text-white italic tracking-tighter">SPOT<span className="text-brick-red">TING</span></h2>
              <button onClick={() => setCurrentView(View.HOME)} className="text-[10px] font-bold text-gray-600 hover:text-white uppercase tracking-widest border border-gray-800 px-4 py-2 transition-colors">Torna Home</button>
            </div>

            {user.isLoggedIn ? (
              <div className="bg-panel-gray border border-gray-800 p-8 mb-16 shadow-2xl relative overflow-hidden">
                <div className="mb-8">
                  <div className="relative w-full aspect-video md:aspect-[21/9] bg-black border border-gray-800 flex items-center justify-center overflow-hidden">
                    {previewUrl ? (
                      <>
                        <img 
                          src={previewUrl} 
                          alt="Preview" 
                          className={`w-full h-full object-contain transition-opacity duration-300 ${isAnalyzing ? 'opacity-30' : 'opacity-100'}`}
                        />
                        {isAnalyzing && (
                          <div className="absolute inset-0 flex flex-col items-center justify-center z-10 bg-black/40 backdrop-blur-sm">
                             <div className="w-12 h-12 border-4 border-brick-red/20 border-t-brick-red rounded-full animate-spin mb-4"></div>
                             <p className="text-[10px] font-bold text-white uppercase tracking-[0.4em]">Analisi AI in corso...</p>
                          </div>
                        )}
                        <button 
                          type="button"
                          onClick={() => { setPreviewUrl(null); setBase64ForAI(null); setScannedCarModel(''); }}
                          className="absolute top-6 right-6 bg-brick-red text-white p-3 hover:scale-110 transition-transform z-20"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
                        </button>
                      </>
                    ) : (
                      <button 
                        type="button"
                        onClick={() => fileInputRef.current?.click()}
                        className="flex flex-col items-center gap-4 group px-12 py-20"
                      >
                        <div className="w-16 h-16 rounded-full border border-gray-800 flex items-center justify-center group-hover:border-brick-red transition-all">
                          <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="1.5"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/></svg>
                        </div>
                        <span className="text-[11px] font-bold uppercase tracking-[0.5em] text-gray-500 group-hover:text-white transition-colors">Carica Foto Avvistamento</span>
                      </button>
                    )}
                  </div>
                  {errorMessage && <p className="mt-4 text-brick-red text-[10px] font-bold uppercase text-center">{errorMessage}</p>}
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                </div>

                <form onSubmit={handleAddSpot} className="flex flex-col md:flex-row gap-4">
                  <div className="flex-1 relative">
                    <input 
                      name="car_model" 
                      placeholder="Modello auto..." 
                      value={scannedCarModel}
                      onChange={(e) => setScannedCarModel(e.target.value)}
                      className="w-full bg-black border border-gray-800 p-4 text-sm outline-none focus:border-brick-red text-white" 
                      required 
                    />
                    {scannedCarModel && !isAnalyzing && (
                      <span className="absolute -top-2 left-3 bg-panel-gray px-2 text-[8px] font-bold text-brick-red uppercase tracking-widest border border-gray-800">Trovata dall'IA</span>
                    )}
                  </div>
                  <button 
                    type="submit" 
                    disabled={!previewUrl || isAnalyzing || isSaving}
                    className={`bg-brick-red text-white font-bold text-xs uppercase tracking-[0.3em] px-10 py-4 hover:brightness-110 transition-all flex items-center justify-center gap-3 ${(!previewUrl || isAnalyzing || isSaving) ? 'opacity-20 cursor-not-allowed' : 'shadow-lg shadow-brick-red/20'}`}
                  >
                    {isSaving && <svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>}
                    Pubblica
                  </button>
                </form>
              </div>
            ) : (
              <div className="bg-panel-gray border border-gray-800 p-16 text-center mb-12 shadow-xl">
                <p className="text-[11px] text-gray-500 uppercase tracking-[0.6em] mb-8">Accedi per condividere i tuoi avvistamenti</p>
                <button onClick={() => setIsAuthModalOpen(true)} className="px-12 py-4 border border-brick-red text-brick-red hover:bg-brick-red hover:text-white text-xs font-bold uppercase tracking-widest transition-all">Accedi / Registrati</button>
              </div>
            )}

            <div className="space-y-12">
              <h3 className="text-[11px] font-bold text-gray-600 uppercase tracking-[0.6em] flex items-center gap-4">
                Recent Spots <div className="flex-1 h-px bg-gray-900"></div>
              </h3>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {spots.length === 0 ? (
                  <p className="col-span-full text-center py-20 text-gray-800 uppercase text-[10px] tracking-[0.5em]">Nessuno spot in archivio.</p>
                ) : (
                  spots.map((spot, idx) => (
                    <div key={spot.id || idx} className="bg-panel-gray border border-gray-800 group hover:border-brick-red/50 transition-all duration-500 overflow-hidden shadow-xl animate-in slide-in-from-bottom-4">
                      <div className="aspect-video bg-black overflow-hidden relative">
                        <img src={spot.image_data} alt={spot.car_model} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                        <div className="absolute top-4 left-4 bg-brick-red text-white text-[8px] font-bold px-2 py-1 uppercase tracking-widest">AVVISTAMENTO</div>
                      </div>
                      <div className="p-6">
                        <div className="flex justify-between items-end mb-4">
                          <h3 className="text-xl font-bold text-white group-hover:text-brick-red transition-colors tracking-tight">{spot.car_model}</h3>
                          <p className="text-[9px] font-bold text-gray-600 uppercase tracking-widest">{spot.spotted_by}</p>
                        </div>
                        <div className="pt-4 border-t border-gray-800 flex justify-between items-center text-[8px] text-gray-700 font-bold uppercase tracking-[0.3em]">
                          <span>{new Date(spot.created_at).toLocaleDateString('it-IT')}</span>
                          <span className="text-brick-red group-hover:translate-x-1 transition-transform">DETAILS →</span>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-4 animate-in fade-in duration-500 max-w-4xl mx-auto">
             <div className="flex flex-col md:flex-row justify-between md:items-center mb-12 border-b border-gray-900 pb-6 gap-6">
              <div className="flex items-center gap-6">
                <h2 className="text-4xl font-brand text-white italic tracking-tighter leading-none">EVENT<span className="text-brick-red">I</span></h2>
                {(user.role === UserRole.ADMIN || user.role === UserRole.ORGANIZER) && (
                  <button 
                    onClick={() => setShowEventForm(!showEventForm)}
                    className="bg-brick-red text-white text-[9px] font-bold uppercase tracking-widest px-4 py-2 hover:brightness-110 transition-all active:scale-95 flex items-center gap-2"
                  >
                    {showEventForm ? '✕ Annulla' : '+ Crea Evento'}
                  </button>
                )}
              </div>
              <button onClick={() => setCurrentView(View.HOME)} className="self-start md:self-auto text-[10px] font-bold text-gray-600 hover:text-white uppercase tracking-widest border border-gray-800 px-4 py-2 transition-colors">Torna Home</button>
            </div>

            {showEventForm && (
              <div className="bg-panel-gray border border-brick-red/30 p-8 mb-12 animate-in slide-in-from-top-4 duration-300 shadow-2xl">
                <h3 className="text-brick-red text-[11px] font-bold uppercase tracking-[0.5em] mb-8">Nuova Sponsorizzazione</h3>
                <form onSubmit={handleCreateEvent} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <InputField label="Titolo Evento" name="title" placeholder="Es: Night Drive Milano" required />
                    <InputField label="Data" name="date" type="date" required />
                    <InputField label="Luogo" name="location" placeholder="Es: Monza (MB)" required />
