interface ProfileModalProps {
  user: User;
  onClose: () => void;
  onLogout: () => void;
  onUpdate: (newData: any) => void;
}

const ProfileModal: React.FC<ProfileModalProps> = ({ user, onClose, onLogout, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'options' | 'data' | 'edit'>('options');
  const [fullData, setFullData] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [editForm, setEditForm] = useState({
    email: '',
    password: '',
    confirmPassword: ''
  });
  const [message, setMessage] = useState({ text: '', type: '' });

  useEffect(() => {
    loadFullData();
  }, []);

  const loadFullData = async () => {
    if (!user.id) return;
    try {
      const data = await db.users.getById(user.id);
      setFullData(data);
      setEditForm(prev => ({ ...prev, email: data.email }));
    } catch (err) {
      console.error("Errore caricamento dati profilo", err);
    }
  };

  const handleBecomeOrganizer = async () => {
    if (user.role === UserRole.ADMIN) {
      alert("Sei già un amministratore!");
      return;
    }
    const confirm = window.confirm("Vuoi attivare il profilo Organizzatore per creare e gestire eventi?");
    if (!confirm) return;

    setIsLoading(true);
    try {
      await db.users.updateRole(user.id!, UserRole.ORGANIZER);
      onUpdate({ ...user, role: UserRole.ORGANIZER });
      setMessage({ text: "Ruolo aggiornato a ORGANIZZATORE!", type: "success" });
      setTimeout(onClose, 2000);
    } catch (err) {
      setMessage({ text: "Errore durante l'aggiornamento.", type: "error" });
    } finally {
      setIsLoading(false);
    }
