              {message.text}
            </div>
          )}

          {activeTab === 'options' && (
            <div className="grid grid-cols-1 gap-4">
              <ProfileOption 
                title="Account Organizzatore" 
                desc="Passa al profilo Pro per sponsorizzare i tuoi eventi" 
