const getCleanErrorMessage = (error: any): string => {
  if (!error) return "Errore ignoto";
  if (typeof error === 'string') return error;
  if (error.message) return error.message;
  if (error.error_description) return error.error_description;
  return JSON.stringify(error);
};

export const db = {
  users: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('users').select('*').order('username');
      if (error) throw new Error(getCleanErrorMessage(error));
      return data || [];
    },
    dangerouslyClearAll: async () => {
      if (!supabase) return false;
      const { error } = await supabase.from('users').delete().not('id', 'is', null);
      if (error) throw new Error("Errore pulizia: " + getCleanErrorMessage(error));
      return true;
    },
    create: async (userData: any) => {
      if (!supabase) return null;
      const isMaster = userData.username?.toLowerCase() === MASTER_USERNAME.toLowerCase();
      try {
        if (isMaster) {
          const { data: existing } = await supabase.from('users').select('id').eq('username', userData.username).maybeSingle();
          if (existing) {
            const { data, error: updateError } = await supabase.from('users').update({ 
              password: userData.password, 
              email: userData.email, 
              role: 'admin' 
            }).eq('id', existing.id).select();
            if (updateError) throw new Error(getCleanErrorMessage(updateError));
            return data[0];
          }
        }

        let role = 'user';
        const { count, error: countError } = await supabase.from('users').select('*', { count: 'exact', head: true });
        if (!countError && (count === 0 || isMaster)) {
          role = 'admin';
        }

        const { data, error: insertError } = await supabase.from('users').insert([
          { username: userData.username, email: userData.email, password: userData.password, role: role }
        ]).select();

        if (insertError) throw new Error(getCleanErrorMessage(insertError));
        return data ? data[0] : null;
      } catch (err: any) {
        throw new Error(getCleanErrorMessage(err));
      }
    },
    update: async (userId: string, updates: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('users').update(updates).eq('id', userId).select();
      if (error) throw new Error(getCleanErrorMessage(error));
      return data[0];
    },
    delete: async (userId: string) => {
      if (!supabase) return false;
      const { error } = await supabase.from('users').delete().eq('id', userId);
      if (error) throw new Error(getCleanErrorMessage(error));
      return true;
    },
    updateRole: async (userId: string, newRole: string) => {
      if (!supabase) return;
      const { data: user, error: getError } = await supabase.from('users').select('username').eq('id', userId).single();
      if (getError) throw new Error(getCleanErrorMessage(getError));
      if (user && user.username.toLowerCase() === MASTER_USERNAME.toLowerCase() && newRole !== 'admin') {
        throw new Error("Non puoi declassare l'amministratore master.");
      }
      const { error: updateError } = await supabase.from('users').update({ role: newRole }).eq('id', userId);
      if (updateError) throw new Error(getCleanErrorMessage(updateError));
    },
    findByUsername: async (identifier: string) => {
      if (!supabase) return null;
      try {
        const { data, error } = await supabase.from('users').select('*').or(`username.eq."${identifier}",email.eq."${identifier}"`).maybeSingle();
        if (error) {
          const { data: fbData } = await supabase.from('users').select('*').eq('username', identifier).maybeSingle();
          if (fbData) return await checkMasterPromotion(fbData);
          const { data: emData } = await supabase.from('users').select('*').eq('email', identifier).maybeSingle();
          return emData ? await checkMasterPromotion(emData) : null;
        }
        return data ? await checkMasterPromotion(data) : null;
      } catch (e) { return null; }
    },
    getById: async (id: string) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('users').select('*').eq('id', id).maybeSingle();
      if (error) throw new Error(getCleanErrorMessage(error));
      return data;
    }
  },

  events: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('events').select('*').order('date', { ascending: true });
      if (error) throw new Error(getCleanErrorMessage(error));
      return data || [];
    },
    create: async (eventData: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('events').insert([eventData]).select();
      if (error) throw new Error(getCleanErrorMessage(error));
      return data[0];
    }
  },

  spots: {
    getAll: async () => {
      if (!supabase) return [];
      const { data, error } = await supabase.from('spots').select('*').order('created_at', { ascending: false });
      if (error) throw new Error(getCleanErrorMessage(error));
      return data || [];
    },
    create: async (spotData: any) => {
      if (!supabase) return null;
      const { data, error } = await supabase.from('spots').insert([spotData]).select();
      if (error) throw new Error(getCleanErrorMessage(error));
      return data[0];
    }
  },

  auth: {
    login: (userData: any) => {
      if (!userData) return null;
      const session = { 
        username: userData.username, 
        role: userData.role, 
        id: userData.id, 
        email: userData.email, // Salviamo anche l'email nella sessione
        timestamp: Date.now() 
      };
      localStorage.setItem(STORAGE_KEYS.SESSION, JSON.stringify(session));
      return session;
    },
    logout: () => localStorage.removeItem(STORAGE_KEYS.SESSION),
    getSession: () => {
      const session = localStorage.getItem(STORAGE_KEYS.SESSION);
      try { return session ? JSON.parse(session) : null; } catch { return null; }
    }
  }
};

async function checkMasterPromotion(user: any) {
  if (user && user.username.toLowerCase() === MASTER_USERNAME.toLowerCase() && user.role !== 'admin') {
    if (supabase) {
      await supabase.from('users').update({ role: 'admin' }).eq('id', user.id);
      user.role = 'admin';
    }
  }
  return user;
}

import React, { useState, useEffect, useRef } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import AuthModal from './components/AuthModal';
import ProfileModal from './components/ProfileModal';
import { View, UserRole, User } from './types';
import { db } from './services/db';
import { identifyCarFromImage } from './services/geminiService';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.HOME);
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
  const [user, setUser] = useState<User>({ isLoggedIn: false });

  const [events, setEvents] = useState<any[]>([]);
  const [spots, setSpots] = useState<any[]>([]);
  const [allUsers, setAllUsers] = useState<any[]>([]);

  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [scannedCarModel, setScannedCarModel] = useState('');
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [base64ForAI, setBase64ForAI] = useState<string | null>(null);

  const [showEventForm, setShowEventForm] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const session = db.auth.getSession();
    if (session && session.username) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id,
        email: session.email // Carichiamo l'email dalla sessione
      });
    }
    loadData();

    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, []);

  const loadData = async () => {
    try {
      console.log("RNI: Inizio caricamento dati...");

      const eventsData = await db.events.getAll();
      console.log("RNI: Eventi caricati con successo.");

      const spotsData = await db.spots.getAll();
      console.log("RNI: Spots caricati con successo.");

      setEvents(eventsData || []);
      setSpots(spotsData || []);
    } catch (err: any) {
      console.error("RNI: Errore caricamento dati:", err.message || err);
      setErrorMessage("Errore di connessione al database. Verifica la configurazione.");
    }
  };

  const loadAllUsers = async () => {
    if (user.role !== UserRole.ADMIN) return;
    try {
      const usersData = await db.users.getAll();
      setAllUsers(usersData);
    } catch (err) {
      console.error("Errore caricamento utenti:", err);
    }
  };

  const handleUpdateUserRole = async (userId: string, newRole: UserRole) => {
    try {
      await db.users.updateRole(userId, newRole);
      setAllUsers(prev => prev.map(u => u.id === userId ? { ...u, role: newRole } : u));
    } catch (err) {
      alert("Errore nell'aggiornamento ruolo.");
    }
  };

  const handleLogin = (userData: any) => {
    if (!userData) return;
    const session = db.auth.login(userData);
    if (session) {
      setUser({ 
        isLoggedIn: true, 
        username: session.username, 
        role: session.role as UserRole,
        id: session.id,
        email: session.email
      });
    }
    setIsAuthModalOpen(false);
  };

  const handleLogout = () => {
    db.auth.logout();
    setUser({ isLoggedIn: false });
    setCurrentView(View.HOME);
    setIsProfileModalOpen(false);
  };

  const handleUpdateUser = (newData: User) => {
    setUser(newData);
    db.auth.login(newData); // Aggiorna sessione locale
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setErrorMessage(null);
    setScannedCarModel('');
    setIsAnalyzing(true);

    if (previewUrl) URL.revokeObjectURL(previewUrl);
    const objectUrl = URL.createObjectURL(file);
    setPreviewUrl(objectUrl);

    const reader = new FileReader();
    reader.onload = async (event) => {
      const fullBase64 = event.target?.result as string;
      setBase64ForAI(fullBase64);

      try {
        const mimeType = file.type || 'image/jpeg';
        const base64Data = fullBase64.split(',')[1];
        const carModel = await identifyCarFromImage(base64Data, mimeType);
        if (carModel && carModel !== 'Sconosciuta') {
          setScannedCarModel(carModel);
        }
      } catch (err: any) {
        setErrorMessage("L'IA ha riscontrato un problema: " + (err.message || "Errore sconosciuto"));
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const handleAddSpot = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!base64ForAI || isSaving) return;

    setIsSaving(true);
    const formData = new FormData(e.currentTarget);
    const carModelInput = (formData.get('car_model') as string) || scannedCarModel || "Auto Sconosciuta";

    const newSpot = {
      car_model: carModelInput,
      location: "Nord Italia",
      spotted_by: user.username || 'Anonimo',
      image_data: base64ForAI,
      created_at: new Date().toISOString()
    };

    try {
      const savedSpot = await db.spots.create(newSpot);
      setSpots(prev => [savedSpot, ...prev]);
      setPreviewUrl(null);
      setBase64ForAI(null);
      setScannedCarModel('');
    } catch (err) {
      alert("Errore durante il salvataggio dello spot.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleCreateEvent = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const eventData = {
      title: formData.get('title'),
      date: formData.get('date'),
      location: formData.get('location'),
      description: formData.get('description'),
      created_by: user.id
    };

    try {
      const newEvent = await db.events.create(eventData);
      setEvents(prev => [newEvent, ...prev].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime()));
      setShowEventForm(false);
    } catch (err) {
      alert("Errore nella creazione dell'evento.");
    }
  };

  return (
    <div className="min-h-screen bg-dark-bg text-light-gray font-sans selection:bg-brick-red selection:text-white">
      <Header 
        onOpenAuth={() => setIsAuthModalOpen(true)} 
