                        <div className="pt-4 border-t border-gray-800 flex justify-between items-center text-[8px] text-gray-700 font-bold uppercase tracking-[0.3em]">
                          <span>{new Date(spot.created_at).toLocaleDateString('it-IT')}</span>
                          <span className="text-brick-red group-hover:translate-x-1 transition-transform">DETAILS →</span>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>
        )}

        {currentView === View.EVENTI && (
          <div className="py-4 animate-in fade-in duration-500 max-w-4xl mx-auto">
             <div className="flex flex-col md:flex-row justify-between md:items-center mb-12 border-b border-gray-900 pb-6 gap-6">
              <div className="flex items-center gap-6">
                <h2 className="text-4xl font-brand text-white italic tracking-tighter leading-none">EVENT<span className="text-brick-red">I</span></h2>
                {(user.role === UserRole.ADMIN || user.role === UserRole.ORGANIZER) && (
                  <button 
                    onClick={() => setShowEventForm(!showEventForm)}
                    className="bg-brick-red text-white text-[9px] font-bold uppercase tracking-widest px-4 py-2 hover:brightness-110 transition-all active:scale-95 flex items-center gap-2"
                  >
                    {showEventForm ? '✕ Annulla' : '+ Crea Evento'}
                  </button>
                )}
              </div>
              <button onClick={() => setCurrentView(View.HOME)} className="self-start md:self-auto text-[10px] font-bold text-gray-600 hover:text-white uppercase tracking-widest border border-gray-800 px-4 py-2 transition-colors">Torna Home</button>
            </div>

            {showEventForm && (
              <div className="bg-panel-gray border border-brick-red/30 p-8 mb-12 animate-in slide-in-from-top-4 duration-300 shadow-2xl">
                <h3 className="text-brick-red text-[11px] font-bold uppercase tracking-[0.5em] mb-8">Nuova Sponsorizzazione</h3>
                <form onSubmit={handleCreateEvent} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-4">
                    <InputField label="Titolo Evento" name="title" placeholder="Es: Night Drive Milano" required />
                    <InputField label="Data" name="date" type="date" required />
                    <InputField label="Luogo" name="location" placeholder="Es: Monza (MB)" required />
                  </div>
                  <div className="space-y-4 flex flex-col">
                    <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-[0.2em]">Descrizione</label>
                    <textarea 
                      name="description" 
                      className="flex-1 bg-black border border-gray-800 p-4 text-white text-sm outline-none focus:border-brick-red resize-none min-h-[120px]" 
                      placeholder="Dettagli dell'evento, orari, punto di ritrovo..."
                      required
                    ></textarea>
                    <button type="submit" className="w-full bg-brick-red text-white py-4 text-xs font-bold uppercase tracking-widest hover:brightness-110 transition-all mt-2 shadow-lg shadow-brick-red/20">Pubblica Evento</button>
                  </div>
                </form>
              </div>
            )}

            <div className="space-y-6">
              {events.length === 0 ? (
                <div className="text-center py-24 border border-dashed border-gray-800">
                  <p className="text-gray-800 uppercase text-[10px] tracking-[0.5em]">Calendario in aggiornamento...</p>
                </div>
              ) : (
                events.map(event => (
                  <div key={event.id} className="bg-panel-gray border border-gray-800 p-8 hover:border-brick-red/40 transition-all group shadow-lg relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-brick-red/5 -mr-16 -mt-16 rounded-full blur-3xl group-hover:bg-brick-red/10 transition-all"></div>
                    <div className="flex flex-col md:flex-row justify-between gap-8 relative z-10">
                      <div className="flex-1">
                        <div className="flex items-center gap-3 mb-4">
                           <span className="text-[10px] font-bold text-brick-red uppercase tracking-widest border border-brick-red/30 px-2 py-0.5">NORD ITALIA</span>
                           <span className="text-[10px] text-gray-600 font-bold uppercase tracking-widest">{new Date(event.date).toLocaleDateString('it-IT')}</span>
                        </div>
                        <h3 className="text-3xl font-bold text-white uppercase tracking-tighter group-hover:text-brick-red transition-colors mb-4">{event.title}</h3>
                        <div className="flex items-center gap-4 text-[11px] text-gray-400 uppercase tracking-[0.2em] font-medium">
                          <span className="flex items-center gap-2"><svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#b03a2e" strokeWidth="2"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg> {event.location}</span>
                        </div>
                        <p className="mt-8 text-sm text-gray-500 italic leading-relaxed max-w-2xl border-l-2 border-gray-800 pl-6 group-hover:border-brick-red/30 transition-colors">"{event.description}"</p>
